import java.util.Map;

public class ClassX {
    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     *
     * @param header El mapa que representa el encabezado del token.
     * @throws IllegalArgumentException Si el encabezado es nulo, no contiene el campo 'alg',
     *                                  o si el valor de 'alg' no es 'HS256'.
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null) {
            throw new IllegalArgumentException("El encabezado del token no puede ser nulo.");
        }

        String algorithm = header.get("alg");

        if (algorithm == null) {
            throw new IllegalArgumentException("El encabezado del token debe contener el campo 'alg'.");
        }

        if (!"HS256".equals(algorithm)) {
            throw new IllegalArgumentException("Algoritmo no compatible. Se esperaba 'HS256', pero se encontró '" + algorithm + "'.");
        }
    }
}
