     */
    public String getRecord(String queryPart) {
        if (queryPart == null || queryPart.trim().isEmpty()) {
            return "Error: Query part cannot be empty.";
        }

        // Sanitize input: Block 'UNION' keyword (case-insensitive)
        if (queryPart.toUpperCase().contains("UNION")) {
            return "Error: 'UNION' keyword is not allowed in the query.";
        }

        // Simulate database access
        // In a real application, this would involve JDBC or an ORM
        // and constructing a safe query (e.g., using PreparedStatement).
        String simulatedRecord = "Record for query part: " + queryPart + " - Data retrieved successfully.";
        return simulatedRecord;
    }

