        ClassX dbService = new ClassX();

        System.out.println("--- Valid Queries ---");
        System.out.println(dbService.getRecord("user_id = 123"));
        System.out.println(dbService.getRecord("product_name = 'Laptop'"));
        System.out.println(dbService.getRecord("order_id = 456 AND status = 'completed'"));

        System.out.println("\n--- Invalid Queries (containing 'UNION') ---");
        System.out.println(dbService.getRecord("user_id = 123 UNION SELECT password FROM users"));
