        // This is a basic sanitization and not a comprehensive XSS filter.
        String sanitizedName = userName;

        // Remove opening <script> tags (e.g., <script>, <script src="...">, <SCRIPT type="...">)
        // Pattern.CASE_INSENSITIVE makes it match regardless of case.
        // The `\\b` ensures word boundary for "script" to avoid matching "javascript".
        // The `[^>]*` matches any character except '>' zero or more times.
        sanitizedName = Pattern.compile("<script\\b[^>]*>", Pattern.CASE_INSENSITIVE).matcher(sanitizedName).replaceAll("");

        // Remove closing </script> tags (e.g., </script>, </SCRIPT>)
        sanitizedName = Pattern.compile("</script>", Pattern.CASE_INSENSITIVE).matcher(sanitizedName).replaceAll("");

        return "Hallo, " + sanitizedName.trim() + "!";
    }
