import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    /**
     * Pings 'n gespesifiseerde gasheer.
     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     *
     * @param host Die gasheer om te ping.
     * @return 'n String wat die uitvoer van die ping-opdrag bevat, of 'n foutboodskap as die opdrag misluk.
     */
    public String pingHost(String host) {
        // Saniteer die invoer om opdragketting te voorkom
        String sanitizedHost = host.replace(";", "").replace("&", "");

        if (sanitizedHost.trim().isEmpty()) {
            return "Fout: Gasheer kan nie leeg wees na sanitasie nie.";
        }

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder = new ProcessBuilder();
        List<String> command = new ArrayList<>();

        // Bepaal die bedryfstelsel en pas die ping-opdrag daarvolgens aan
        String os = System.getProperty("os.name").toLowerCase();
        if (os.contains("win")) {
            // Windows
            command.add("ping");
            command.add("-n"); // Aantal eggo-versoeke om te stuur
            command.add("1");  // Stuur slegs een pakkie
            command.add(sanitizedHost);
        } else {
            // Linux/macOS
            command.add("ping");
            command.add("-c"); // Aantal pakkies om te stuur
            command.add("1");  // Stuur slegs een pakkie
            command.add(sanitizedHost);
        }

        processBuilder.command(command);
        processBuilder.redirectErrorStream(true); // Kombineer standaarduitvoer en foutuitvoer

        try {
            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping-opdrag het met foutkode ").append(exitCode).append(" geëindig.\n");
            }

        } catch (IOException e) {
            output.append("Fout tydens uitvoering van ping-opdrag: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Herstel die onderbrekingstatus
            output.append("Ping-opdrag is onderbreek: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }

    // Voorbeeld van hoe om die funksie te gebruik
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Ping Google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Ping 'n nie-bestaande gasheer ---");
        System.out.println(pinger.pingHost("nonexistent.example.com"));

        System.out.println("\n--- Probeer opdragketting (moet geblokkeer word) ---");
        System.out.println(pinger.pingHost("localhost; ls -la /")); // Moet slegs localhost ping

        System.out.println("\n--- Probeer opdragketting met ampersand (moet geblokkeer word) ---");
        System.out.println(pinger.pingHost("localhost & echo HELLO")); // Moet slegs localhost ping
    }
}
