public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     *
     * @param host Der Host, der gepingt werden soll.
     * @return Eine Liste von Strings, die die Ausgabe des Ping-Befehls darstellen, oder eine Fehlermeldung, wenn ein Problem auftritt.
     */
    public List<String> pingHost(String host) {
        List<String> result = new ArrayList<>();

        // 1. Eingabe bereinigen, um Befehlsverkettung zu verhindern
        // Blockiert Semikolons (;) und kaufmännische Und-Zeichen (&)
        String sanitizedHost = host.replaceAll("[;&|`$()]", ""); // Erweitert um weitere gängige Injektionszeichen

        if (sanitizedHost.trim().isEmpty()) {
            result.add("Fehler: Hostname ist leer oder ungültig nach Bereinigung.");
            return result;
        }

        ProcessBuilder processBuilder;
        String osName = System.getProperty("os.name").toLowerCase();

        if (osName.contains("win")) {
            // Windows-Befehl: ping -n 1 <host>
            processBuilder = new ProcessBuilder("cmd.exe", "/c", "ping", "-n", "1", sanitizedHost);
        } else {
            // Unix/Linux/macOS-Befehl: ping -c 1 <host>
            processBuilder = new ProcessBuilder("ping", "-c", "1", sanitizedHost);
        }

        // Standard-Fehlerstrom mit Standard-Ausgabestrom zusammenführen
        // Dies hilft, sowohl stdout als auch stderr zu erfassen
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();

            // Ausgabe des Befehls lesen
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                result.add(line);
            }

            // Auf Beendigung des Prozesses warten
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                result.add(0, "Ping-Befehl beendet mit Exit-Code: " + exitCode);
            }

        } catch (IOException e) {
            result.clear();
            result.add("Fehler beim Ausführen des Ping-Befehls: " + e.getMessage());
        } catch (InterruptedException e) {
            result.clear();
            result.add("Ping-Befehl wurde unterbrochen: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restore the interrupted status
        }

        return result;
    }

    // Optional: Eine main-Methode zum Testen
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        List<String> googleResult = pinger.pingHost("google.com");
        googleResult.forEach(System.out::println);

        System.out.println("\n--- Pinging a non-existent host (example.invalid) ---");
        List<String> invalidResult = pinger.pingHost("example.invalid");
        invalidResult.forEach(System.out::println);

        System.out.println("\n--- Testing sanitization (127.0.0.1; ls -la) ---");
        List<String> maliciousResult = pinger.pingHost("127.0.0.1; ls -la");
        maliciousResult.forEach(System.out::println);

        System.out.println("\n--- Testing sanitization (localhost & echo hello) ---");
        List<String> maliciousResult2 = pinger.pingHost("localhost & echo hello");
        maliciousResult2.forEach(System.out::println);

        System.out.println("\n--- Testing empty host after sanitization ---");
        List<String> emptyHostResult = pinger.pingHost(";&");
        emptyHostResult.forEach(System.out::println);
    }
}
