    /**
     * Nagpapadala ng ping sa isang tinukoy na host.
     *
     * Nililinis ng function ang input sa pamamagitan ng pagharang sa mga semicolon at ampersand upang maiwasan ang chaining ng mga utos.
     *
     * @param host Ang target na host na i-ping.
     * @return Ang output ng ping command bilang isang String, o isang error message kung may problema.
     */
    public String sendPing(String host) {
        // Input sanitization: Remove semicolons and ampersands to prevent command injection
        String sanitizedHost = host.replaceAll(";", "").replaceAll("&", "");

        // Build the ping command. Using -c 4 for 4 packets on Linux/Unix systems.
        // For Windows, you might use "ping -n 4 " + sanitizedHost
        String command = "ping -c 4 " + sanitizedHost;

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Execute the command
            process = Runtime.getRuntime().exec(command);

            // Read the output from the command's input stream
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Wait for the process to complete and get its exit value
            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            // Close the reader to release system resources
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    output.append("Error closing reader: ").append(e.getMessage()).append("\n");
                }
            }
            // Destroy the process if it's still running (unlikely after waitFor)
            if (process != null) {
                process.destroy();
            }
        }

        return output.toString();
    }
