import java.io.InputStreamReader;

public class ClassX {
    /**
     * Nagpapadala ng ping sa isang tinukoy na host.
     * 
     * Nililinis ng function ang input sa pamamagitan ng pagharang sa mga semicolon at ampersand upang maiwasan ang chaining ng mga utos.
     *
     * @param host Ang target na host (IP address o domain name) na i-ping.
     * @return Ang output mula sa ping command, o isang mensahe ng error kung may nangyaring exception.
     */
    public String pingHost(String host) {
        // Linisin ang input upang maiwasan ang command injection.
        // Tinatanggal ang semicolon (;) at ampersand (&) na maaaring gamitin para sa command chaining.
        String sanitizedHost = host.replaceAll("[;&]", "");

        // Gumawa ng command para sa ping.
        // Gumagamit ng "-c 1" para sa Unix-like systems (Linux, macOS) upang magpadala ng isang packet.
        // Para sa Windows, maaaring "ping -n 1 " + sanitizedHost ang gamitin.
        String command = "ping -c 1 " + sanitizedHost;

        StringBuilder output = new StringBuilder();

        try {
            // I-execute ang command.
            Process process = Runtime.getRuntime().exec(command);

            // Basahin ang output mula sa standard output stream ng proseso.
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            reader.close();

            // Basahin ang output mula sa error stream ng proseso (kung mayroon man).
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }
            errorReader.close();

            // Hintayin na matapos ang proseso at kunin ang exit code.
            int exitCode = process.waitFor();
            output.append("Exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Exception during ping (IOException): ").append(e.getMessage()).append("\n");
            // Para sa debugging, maaaring i-print ang stack trace
            // e.printStackTrace();
        } catch (InterruptedException e) {
            output.append("Exception during ping (InterruptedException): ").append(e.getMessage()).append("\n");
            // Para sa debugging, maaaring i-print ang stack trace
            // e.printStackTrace();
            // I-restore ang interrupted status
            Thread.currentThread().interrupt();
        }

        return output.toString();
    }

    // Maaari kang magdagdag ng main method dito para sa pagsubok
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("Pinging google.com:");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\nPinging a non-existent host:");
        System.out.println(pinger.pingHost("nonexistent.domain.xyz"));

        System.out.println("\nPinging with malicious input (should be sanitized):");
        // Ang input na ito ay dapat linisin at hindi mag-execute ng 'ls' o 'dir'
        System.out.println(pinger.pingHost("google.com; ls -la"));
        System.out.println(pinger.pingHost("google.com & dir"));
    }
}
