        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }

        // Block semicolons and ampersands
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$")) {
            throw new IllegalArgumentException("Host contains disallowed characters: ;, &, |, `, $");
        }

        // Determine the OS to choose the correct ping command
        String osName = System.getProperty("os.name").toLowerCase();
        List<String> command = new ArrayList<>();

        if (osName.contains("win")) {
            // Windows
            command.add("cmd.exe");
            command.add("/c");
            command.add("ping");
            command.add("-n"); // Number of echo requests to send
            command.add("4");
            command.add(host);
        } else if (osName.contains("nix") || osName.contains("mac") || osName.contains("linux")) {
            // Unix-like systems (Linux, macOS)
            command.add("ping");
            command.add("-c"); // Number of packets to send
            command.add("4");
            command.add(host);
        } else {
            throw new UnsupportedOperationException("Unsupported operating system: " + osName);
        }

