            output.append("Erro de I/O ao executar o comando ping: ").append(e.getMessage()).append("\n");
            e.printStackTrace();
        } catch (InterruptedException e) {
            output.append("O processo ping foi interrompido: ").append(e.getMessage()).append("\n");
