import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pingea un host especificado.
     * 
     * La función sanitiza la entrada bloqueando punto y coma y ampersands para prevenir la encadenación de comandos.
     * 
     * @param host El nombre de host o dirección IP a pingear.
     * @return true si el comando se ejecutó sin errores, false en caso contrario.
     */
    public boolean pingHost(String host) {
        // Sanitizar la entrada para prevenir la inyección de comandos
        // Bloquear punto y coma y ampersands
        String sanitizedHost = host.replaceAll("[;&]", "");

        if (sanitizedHost.trim().isEmpty()) {
            System.err.println("Error: El host sanitizado está vacío.");
            return false;
        }

        String osName = System.getProperty("os.name").toLowerCase();
        String command;
        if (osName.contains("win")) {
            // Comando ping para Windows
            command = "ping -n 1 " + sanitizedHost;
        } else {
            // Comando ping para sistemas Unix-like (Linux, macOS)
            command = "ping -c 1 " + sanitizedHost;
        }

        Process process = null;
        try {
            System.out.println("Ejecutando comando: " + command);
            process = Runtime.getRuntime().exec(command);

            // Leer la salida estándar del comando
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String s;
            System.out.println("Salida del comando ping:");
            while ((s = stdInput.readLine()) != null) {
                System.out.println(s);
            }

            // Leer la salida de error del comando
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            System.out.println("Salida de error del comando ping (si la hay):");
            while ((s = stdError.readLine()) != null) {
                System.err.println(s);
            }

            // Esperar a que el proceso termine y obtener el código de salida
            int exitCode = process.waitFor();
            System.out.println("El comando ping terminó con código de salida: " + exitCode);

            // Un código de salida de 0 generalmente indica éxito para el comando ping
            return exitCode == 0;

        } catch (IOException e) {
            System.err.println("Error de E/S al ejecutar el comando ping: " + e.getMessage());
            e.printStackTrace();
            return false;
        } catch (InterruptedException e) {
            System.err.println("El proceso ping fue interrumpido: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restaurar el estado de interrupción
            return false;
        } finally {
            if (process != null) {
                // Asegurarse de destruir el proceso si aún está en ejecución
                // Aunque waitFor() ya lo hace, es una buena práctica.
                process.destroy(); 
            }
        }
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("\n--- Prueba 1: Host válido (google.com) ---");
        pinger.pingHost("google.com");

        System.out.println("\n--- Prueba 2: Host válido (127.0.0.1) ---");
        pinger.pingHost("127.0.0.1");

        System.out.println("\n--- Prueba 3: Host con intento de inyección (google.com; ls) ---");
        pinger.pingHost("google.com; ls"); // Debería ser sanitizado a "google.com"

        System.out.println("\n--- Prueba 4: Host con intento de inyección (google.com && echo hello) ---");
        pinger.pingHost("google.com && echo hello"); // Debería ser sanitizado a "google.com"

        System.out.println("\n--- Prueba 5: Host inexistente (nonexistent.domain) ---");
        pinger.pingHost("nonexistent.domain");

        System.out.println("\n--- Prueba 6: Host vacío ---");
        pinger.pingHost("");

        System.out.println("\n--- Prueba 7: Solo caracteres de inyección ---");
        pinger.pingHost(";&"); // Debería resultar en un host vacío después de sanitizar
    }
}
