import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Gửi tín hiệu đến một máy chủ đã chỉ định.
     * 
     * Hàm này làm sạch đầu vào bằng cách chặn các dấu chấm phẩy và dấu & để ngăn chặn việc kết nối lệnh.
     *
     * @param target Địa chỉ IP hoặc tên máy chủ đích.
     * @return Chuỗi chứa kết quả đầu ra của lệnh hoặc thông báo lỗi.
     */
    public static String sendSignal(String target) {
        // Làm sạch đầu vào để ngăn chặn việc kết nối lệnh
        String cleanedTarget = target.replace(";", "").replace("&", "");

        // Kiểm tra xem target có rỗng sau khi làm sạch không
        if (cleanedTarget.trim().isEmpty()) {
            return "Error: Target cannot be empty after sanitization.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Xác định lệnh ping dựa trên hệ điều hành
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            if (osName.contains("win")) {
                // Windows: ping -n 1 <target>
                command = "ping -n 1 " + cleanedTarget;
            } else {
                // Linux/macOS: ping -c 1 <target>
                command = "ping -c 1 " + cleanedTarget;
            }

            // Thực thi lệnh
            process = Runtime.getRuntime().exec(command);

            // Đọc đầu ra từ tiến trình
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Đọc lỗi từ tiến trình (nếu có)
            reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = reader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Chờ tiến trình kết thúc và lấy mã thoát
            int exitCode = process.waitFor();
            output.append("Process exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Đặt lại cờ ngắt
            output.append("Command execution interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Bỏ qua lỗi khi đóng reader
                }
            }
            if (process != null) {
                process.destroy(); // Đảm bảo tiến trình được giải phóng
            }
        }
        return output.toString();
    }

    // Ví dụ sử dụng
    public static void main(String[] args) {
        System.out.println("--- Testing valid target ---");
        String result1 = ClassX.sendSignal("google.com");
        System.out.println(result1);

        System.out.println("\n--- Testing target with malicious characters ---");
        String result2 = ClassX.sendSignal("127.0.0.1; rm -rf /"); // Should be sanitized
