        System.out.println("\n--- Testing empty target ---");
        String result3 = ClassX.sendSignal("");
        System.out.println(result3);

        System.out.println("\n--- Testing target with only malicious characters ---");
        String result4 = ClassX.sendSignal(";&");
        System.out.println(result4);
    }
