import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pinga un host specificato.
     * 
     * La funzione sanifica l'input bloccando i punti e virgola e le e commerciali per prevenire la concatenazione dei comandi.
     * 
     * @param host L'indirizzo IP o il nome host da pingare.
     * @return Una stringa contenente l'output del comando ping, o un messaggio di errore in caso di fallimento o input non valido.
     */
    public String pingHost(String host) {
        // Sanificazione dell'input per prevenire command injection
        if (host == null || host.isEmpty()) {
            return "Errore: L'host non può essere nullo o vuoto.";
        }
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("&&") || host.contains("||")) {
            return "Errore di sicurezza: Caratteri non consentiti rilevati nell'input dell'host.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            if (osName.contains("win")) {
                // Per Windows: ping -n 1 <host>
                command = "ping -n 1 " + host;
            } else {
                // Per Linux/macOS: ping -c 1 <host>
                command = "ping -c 1 " + host;
            }

            process = Runtime.getRuntime().exec(command);

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Attendere la fine del processo e controllare il codice di uscita
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                // Se il ping non ha successo, leggere anche l'errore standard
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("ERRORE: ").append(errorLine).append("\n");
                }
                if (output.length() == 0) { // Se non c'è output di errore specifico
                     output.append("Il comando ping per '").append(host).append("' ha fallito con codice di uscita: ").append(exitCode).append("\n");
                }
            }

        } catch (IOException e) {
            output.append("Errore I/O durante l'esecuzione del ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Ripristina lo stato di interruzione
            output.append("Il processo di ping è stato interrotto: ").append(e.getMessage()).append("\n");
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Ignora o logga l'errore nella chiusura del reader
                }
            }
            if (process != null) {
                process.destroy(); // Assicurati che il processo sia terminato
            }
        }

        return output.toString();
    }

    // Esempio di utilizzo
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Ping di Google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Ping di un IP locale (es. router) ---");
        System.out.println(pinger.pingHost("192.168.1.1")); // Sostituisci con un IP valido nella tua rete

        System.out.println("\n--- Ping di un host inesistente ---");
        System.out.println(pinger.pingHost("nonexistent.domain.xyz"));

        System.out.println("\n--- Tentativo di injection (dovrebbe essere bloccato) ---");
        System.out.println(pinger.pingHost("google.com; ls -la"));

        System.out.println("\n--- Host vuoto (dovrebbe essere bloccato) ---");
        System.out.println(pinger.pingHost(""));
    }
}
