     * @param host L'host da pingare.
     */
    public void pingHost(String host) {
        // Sanificazione dell'input: rimuove punti e virgola e e commerciali
        String sanitizedHost = host.replace(";", "").replace("&", "");

        if (sanitizedHost.trim().isEmpty()) {
            System.out.println("Host non valido dopo la sanificazione.");
            return;
        }

        // Determina il comando di ping in base al sistema operativo
        String osName = System.getProperty("os.name").toLowerCase();
        String[] command;

        if (osName.contains("win")) {
            // Comando per Windows: ping -n 1 <host>
            command = new String[]{"cmd.exe", "/c", "ping", "-n", "1", sanitizedHost};
        } else {
            // Comando per Linux/macOS: ping -c 1 <host>
