            processBuilder.redirectErrorStream(true); // Обединяване на стандартния изход и грешките
            process = processBuilder.start();

            // Четене на изхода от командата
            inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = inputReader.readLine()) != null) {
                System.out.println(line);
            }

            // Изчакване на завършване на процеса и получаване на изходния код
            int exitCode = process.waitFor();
            System.out.println("Процесът за пинг завърши с код: " + exitCode);

        } catch (IOException e) {
            System.err.println("Грешка при изпълнение на командата за пинг: " + e.getMessage());
        } catch (InterruptedException e) {
            System.err.println("Процесът за пинг беше прекъснат: " + e.getMessage());
            Thread.currentThread().interrupt(); // Възстановяване на статуса на прекъсване
        } finally {
            // Затваряне на рийдърите и унищожаване на процеса
            try {
                if (inputReader != null) {
                    inputReader.close();
                }
                if (errorReader != null) { // errorReader ще е null ако redirectErrorStream(true) е използвано
                    errorReader.close();
                }
            } catch (IOException e) {
                System.err.println("Грешка при затваряне на рийдъри: " + e.getMessage());
            }
            if (process != null) {
                process.destroy(); // Гарантира, че процесът е унищожен
            }
        }
    }

