     * path traversal by checking if the member name contains '..'.
     *
     * @param zipFilePath The path to the zip file.
     * @param destDirectory The directory where the contents will be extracted.
     * @throws IOException If an I/O error occurs, or a path traversal attempt is detected.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs(); // Create destination directory and any necessary parent directories
        }

        // Buffer for reading data
        byte[] buffer = new byte[1024];

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Iterate over entries in the zip file
            while (entry != null) {
                String entryName = entry.getName();

                // Path traversal check: Prevent extracting files outside the destination directory
                // by checking for '..' in the entry name.
                if (entryName.contains("..")) {
                    throw new IOException("Path traversal attempt detected in zip entry: " + entryName);
                }

                File newFile = new File(destDir, entryName);

                // If the entry is a directory, create it
                if (entry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Ensure parent directories exist for the file
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Write the file content
