                    throw new IOException("Entri zip mencoba menulis di luar direktori tujuan: " + entryName);
                }

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Gagal membuat direktori: " + newFile);
                    }
                } else {
                    // Pastikan direktori induk ada
