     * 
     * این تابع از طریق اعضای آرشیو تکرار می‌کند و سعی می‌کند از عبور مسیر جلوگیری کند با بررسی اینکه آیا نام عضو شامل '..' است یا خیر.
     *
     * @param zipFilePath مسیر فایل zip برای استخراج.
     * @param destDirectory مسیر دایرکتوری مقصد که فایل‌ها در آن استخراج می‌شوند.
     * @throws IOException اگر خطایی در عملیات ورودی/خروجی رخ دهد.
     */
    public void extractZip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();

            while (zipEntry != null) {
                String entryName = zipEntry.getName();

                // Path traversal prevention: Check for ".." in the entry name
                // Also, ensure the entry name doesn't start with path separators
                // which could lead to absolute paths or paths outside the destination.
                if (entryName.contains("..") || entryName.startsWith("/") || entryName.startsWith("\\")) {
                    System.err.println("Skipping potentially malicious zip entry: " + entryName);
                    zipEntry = zis.getNextEntry();
                    continue;
                }

                File newFile = new File(destDir, entryName);

