import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Entpackt ein Zip-Archiv an das angegebene Ziel, nachdem die Mitgliedspfade überprüft wurden.
     *
     * Die Funktion durchläuft die Mitglieder des Archivs und versucht, Pfadtraversierung zu verhindern, indem sie überprüft, ob der Mitgliedsname '..' enthält.
     *
     * @param zipFilePath Der vollständige Pfad zur Zip-Datei.
     * @param destDirectory Das Zielverzeichnis, in das die Dateien entpackt werden sollen.
     * @throws IOException Wenn ein E/A-Fehler auftritt oder eine Pfadtraversierung erkannt wird.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Get the canonical path of the destination directory to prevent path traversal
        String destDirPath = destDir.getCanonicalPath();

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // iterates over entries in the zip file
            while (entry != null) {
                String entryName = entry.getName();
                File newFile = new File(destDir, entryName);

                // Security check: Prevent path traversal
                // Get the canonical path of the new file
                String newFilePath = newFile.getCanonicalPath();

                // Ensure that the new file's canonical path starts with the destination directory's canonical path
                // This prevents entries like "../../../etc/passwd" from being written outside the target directory
                if (!newFilePath.startsWith(destDirPath + File.separator)) {
                    throw new IOException("Entry is outside of the target directory: " + entryName);
                }

                if (entry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Ensure parent directories exist for file entries
                    File parent = newFile.getParentFile();
                    if (!parent.isDirectory() && !parent.mkdirs()) {
                        throw new IOException("Failed to create directory " + parent);
                    }

                    // Write the file content
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zipIn.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
}
