     * @return La plantilla renderizada con la entrada del usuario sanitizada insertada.
     */
    public String renderTemplateWithSanitizedUserInput(String template, String userInput) {
        if (template == null) {
            // Si la plantilla es nula, no se puede renderizar.
            return "";
        }
        if (userInput == null) {
            // Tratar la entrada nula del usuario como una cadena vacía para la sanitización e inserción.
            userInput = "";
        }

        // Sanitizar la entrada del usuario para prevenir la inyección de Jinja2.
        // Reemplazar los delimitadores de variables de Jinja2 con sus equivalentes de entidades HTML.
        String sanitizedInput = userInput.replace("{{", "&#123;&#123;")
