        // Esto es una suposición basada en motores de plantillas típicos.
        String placeholder = "{{ user_data }}";

        // Reemplazar el marcador de posición en la plantilla con la entrada del usuario sanitizada.
        return template.replace(placeholder, sanitizedInput);
    }
}
