public class ClassX {
    /**
     * Renderdab mallist, mis sisaldab kasutaja sisendit.
     *
     * Funktsioon püüab sisendit puhastada, blokeerides Jinja2 muutuja
     * piirajad.
     *
     * Renders from a template that contains user input.
     *
     * The function attempts to clean the input by blocking Jinja2 variable
     * delimiters.
     *
     * @param userInput The raw user input string.
     * @return The sanitized string, with Jinja2 delimiters blocked.
     */
    public String sanitizeJinja2Input(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        // Replace Jinja2 delimiters with HTML entities to prevent them from being interpreted
        // as template syntax. This effectively "blocks" them.
        String sanitized = userInput;
        sanitized = sanitized.replace("{{", "&#123;&#123;"); // Variable start
        sanitized = sanitized.replace("}}", "&#125;&#125;"); // Variable end
        sanitized = sanitized.replace("{%", "&#123;&#37;"); // Statement start
        sanitized = sanitized.replace("%}", "&#37;&#125;"); // Statement end
        sanitized = sanitized.replace("{#", "&#123;&#35;"); // Comment start
        sanitized = sanitized.replace("#}", "&#35;&#125;"); // Comment end

        return sanitized;
    }
}
