import java.net.URL;

public class ClassX {
    /**
     * Fetches content from a generated URL after validating the host.
     *
     * This function sanitizes the host by checking for invalid characters like spaces.
     *
     * @param host The hostname to connect to.
     * @return The content fetched from the URL as a String, or an error message if validation or fetching fails.
     */
    public String fetchContent(String host) {
        // 1. Sanitize and validate the host
        if (host == null || host.trim().isEmpty()) {
            return "Error: Host cannot be null or empty.";
        }

        // Check for spaces or other potentially problematic characters.
        // A more robust validation might use a regex for valid hostnames,
        // but for this example, we specifically check for whitespace characters.
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
            return "Error: Host contains invalid whitespace characters.";
        }

        URL url = null;
        try {
            // 2. Generate the URL
            // For simplicity, using HTTP and root path. In a real scenario,
            // scheme and path might be configurable or part of the host string.
            url = new URL("http://" + host + "/");

            // 3. Fetch content from the URL
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
                return content.toString();
            }
        } catch (MalformedURLException e) {
            // This exception indicates that the generated URL string is not a valid URL.
            // This could happen if the 'host' string, despite initial checks,
            // leads to an unparseable URL.
            return "Error: Malformed URL generated for host '" + host + "'. Details: " + e.getMessage();
        } catch (IOException e) {
            // This exception covers network-related issues during the connection or reading process.
            return "Error: Could not fetch content from '" + (url != null ? url.toString() : "unknown URL") + "'. Details: " + e.getMessage();
        }
    }
}

