            throw new MalformedURLException("Failed to construct URL with host '" + host + "' and path '" + path + "': " + e.getMessage());
        }

        // 3. Fetch content from the URL
        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Optional: Set connection timeouts to prevent indefinite waiting
        connection.setConnectTimeout(5000); // 5 seconds to establish connection
        connection.setReadTimeout(10000);   // 10 seconds to read data

