     */
    public String getContentFromUrl(String host) throws MalformedURLException, IOException {
        // 1. 清理主机字符串：移除首尾空格
        String cleanedHost = host.trim();

        // 2. 确保主机包含协议，如果缺少则默认为 http://
        if (!cleanedHost.startsWith("http://") && !cleanedHost.startsWith("https://")) {
            cleanedHost = "http://" + cleanedHost;
