        String host = url.getHost();

        // Validate host for null or empty string
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("URL host cannot be null or empty.");
        }

        // Validate host for invalid whitespace characters as per description ("tühikud").
        // Hostnames typically do not contain spaces, tabs, newlines, or carriage returns.
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
            throw new IllegalArgumentException("URL host contains invalid whitespace characters.");
        }

        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Set reasonable timeouts to prevent hanging connections
        connection.setConnectTimeout(5000); // 5 seconds for connection establishment
        connection.setReadTimeout(5000);    // 5 seconds for reading data

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
