    public String getSanitizedUrlContent(String host, String path) throws IOException {
        // 1. Sanitización del host
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host inválido: El host no puede ser nulo o vacío.");
        }
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
