     */
    public String getContentFromUrl(String host) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }

        // 1. Очистка хоста
        String sanitizedHost = host.trim();

        // Простая проверка на недопустимые символы, такие как встроенные пробелы.
        // Более строгая проверка может включать регулярные выражения для валидации доменных имен.
        if (sanitizedHost.contains(" ")) {
