import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Haal inhoud van 'n gegenereerde URL af nadat die gasheer geverifieer is.
     *
     * Hierdie funksie saniteer die gasheer deur te kyk vir ongeldige karakters soos spaties.
     *
     * @param host Die gasheer wat gesaniteer en gebruik moet word.
     * @param path Die pad na die hulpbron op die gasheer.
     * @return Die inhoud van die URL as 'n String, of null as 'n fout voorkom.
     */
    public String fetchContentFromVerifiedHost(String host, String path) {
        // Saniteer die gasheer deur ongeldige karakters soos spaties te verwyder.
        // Spaties is nie geldig in 'n gasheernaam nie.
        String sanitizedHost = host.replaceAll("\\s+", "");

        if (sanitizedHost.isEmpty()) {
            System.err.println("Gesaniteerde gasheer is leeg. Kan nie 'n URL genereer nie.");
            return null;
        }

        URL url = null;
        try {
            // Genereer die URL. Ons gebruik "http" as die protokol vir hierdie voorbeeld.
            // Vir produksie-omgewings, oorweeg "https".
            url = new URL("http", sanitizedHost, path);
        } catch (MalformedURLException e) {
            System.err.println("Fout met die generering van URL vir gasheer '" + sanitizedHost + "' en pad '" + path + "': " + e.getMessage());
            return null;
        }

        StringBuilder content = new StringBuilder();
        HttpURLConnection connection = null;
        try {
            // Maak 'n verbinding met die URL
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET"); // Stel die HTTP metode na GET
            connection.setConnectTimeout(5000); // 5 sekonde verbinding tydsbeperking
            connection.setReadTimeout(5000);    // 5 sekonde lees tydsbeperking

            int responseCode = connection.getResponseCode();

            // Kontroleer of die HTTP-antwoord suksesvol was (200 OK)
            if (responseCode == HttpURLConnection.HTTP_OK) {
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        content.append(line).append("\n");
                    }
                }
            } else {
                System.err.println("HTTP foutkode: " + responseCode + " vir URL: " + url);
                // Lees die foutstroom as dit beskikbaar is
                try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(connection.getErrorStream()))) {
                    String errorLine;
                    StringBuilder errorContent = new StringBuilder();
                    while ((errorLine = errorReader.readLine()) != null) {
                        errorContent.append(errorLine).append("\n");
                    }
                    if (errorContent.length() > 0) {
                        System.err.println("Foutboodskap van bediener: " + errorContent.toString());
                    }
                } catch (IOException e) {
                    // Ignore, error stream might not be available
                }
                return null;
            }
        } catch (IOException e) {
            System.err.println("Fout tydens die aflaai van inhoud van " + url + ": " + e.getMessage());
            return null;
        } finally {
            // Maak seker die verbinding word gesluit
            if (connection != null) {
                connection.disconnect();
            }
        }

        return content.toString();
    }
}
