     * Recupera contenuti da un URL generato dopo aver convalidato l'host.
     *
     * Questa funzione sanifica l'host controllando la presenza di caratteri non validi come gli spazi.
     *
     * @param host L'host da convalidare e utilizzare per costruire l'URL.
     * @param path Il percorso da utilizzare per costruire l'URL.
     * @return Il contenuto recuperato dall'URL come stringa.
     * @throws MalformedURLException Se l'host sanificato o il percorso risultano in un URL non valido.
     * @throws IOException Se si verifica un errore durante la lettura del contenuto dall'URL.
     * @throws IllegalArgumentException Se l'host fornito è nullo, vuoto o diventa vuoto dopo la sanitizzazione.
     */
    public String retrieveContentFromValidatedUrl(String host, String path) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("L'host non può essere nullo o vuoto.");
        }
        if (path == null) {
            path = ""; // Tratta un percorso nullo come un percorso vuoto
        }

        // Sanifica l'host rimuovendo gli spazi e altri caratteri di spaziatura.
        // Per una sanitizzazione più robusta, si potrebbe considerare una whitelist di caratteri validi.
        String sanitizedHost = host.replaceAll("[\\s]", "");

        if (sanitizedHost.isEmpty()) {
            throw new IllegalArgumentException("L'host sanificato non può essere vuoto dopo la rimozione dei caratteri non validi.");
        }

        // Costruisci l'URL. Si assume il protocollo HTTPS per una maggiore sicurezza.
        // Se è richiesto HTTP, cambiare "https" in "http".
        URL url = new URL("https", sanitizedHost, path);

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
