public class ClassX {
    /**
     * Simule la fonction mailcap.findmatch. 
     * Construit une commande pour afficher le fichier en fonction du mime_type et l'exécute.
     * 
     * Cette implémentation inclut une vérification pour empêcher la chaîne de commandes en bloquant les points-virgules.
     * 
     * @param mimeType Le type MIME du fichier à afficher.
     * @param filePath Le chemin d'accès au fichier à afficher.
     * @return Le code de sortie de la commande exécutée.
     * @throws IOException Si une erreur d'E/S se produit lors de l'exécution de la commande.
     * @throws InterruptedException Si le processus en cours est interrompu pendant qu'il attend la fin de la commande.
     */
    public int findAndExecuteMatch(String mimeType, String filePath) throws IOException, InterruptedException {
        // Basic validation to prevent command chaining by blocking semicolons
        if (mimeType.contains(";") || filePath.contains(";")) {
            System.err.println("Error: Semicolons are not allowed in mimeType or filePath to prevent command injection.");
            return -1; // Indicate an error
        }

        // In a real mailcap.findmatch, you would parse mailcap files
        // (e.g., /etc/mailcap, ~/.mailcap) to find the appropriate viewer command
        // based on the mimeType.
        // For this simulation, we'll use a simplified mapping or a default viewer.

        String command = "";

        // Simplified logic for demonstration purposes
        // In a real scenario, this would be much more sophisticated,
        // potentially involving a configuration file or a more complex switch.
        switch (mimeType) {
            case "text/plain":
                // Using 'cat' for text files on Unix-like systems, 'type' on Windows
                if (System.getProperty("os.name").toLowerCase().contains("win")) {
                    command = "cmd /c type \"" + filePath + "\"";
                } else {
                    command = "cat \"" + filePath + "\"";
                }
                break;
            case "image/jpeg":
            case "image/png":
                // Using 'xdg-open' for images on Unix-like systems, 'start' on Windows
                if (System.getProperty("os.name").toLowerCase().contains("win")) {
                    command = "cmd /c start \"" + filePath + "\"";
                } else {
                    command = "xdg-open \"" + filePath + "\"";
                }
                break;
            case "application/pdf":
                // Using 'xdg-open' for PDFs on Unix-like systems, 'start' on Windows
                if (System.getProperty("os.name").toLowerCase().contains("win")) {
                    command = "cmd /c start \"" + filePath + "\"";
                } else {
                    command = "xdg-open \"" + filePath + "\"";
                }
                break;
            default:
                System.err.println("No specific viewer found for MIME type: " + mimeType);
                // Fallback to a generic open command if possible
                if (System.getProperty("os.name").toLowerCase().contains("win")) {
                    command = "cmd /c start \"" + filePath + "\"";
                } else {
                    command = "xdg-open \"" + filePath + "\"";
                }
                // If xdg-open or start isn't suitable, you might want to return an error here
                // return -1;
        }

        if (command.isEmpty()) {
            System.err.println("Could not determine a command for MIME type: " + mimeType);
            return -1;
        }

        System.out.println("Executing command: " + command);

        Process process;
        if (System.getProperty("os.name").toLowerCase().contains("win")) {
            // For Windows, Runtime.exec(String) might have issues with spaces in paths
            // if not properly quoted or if the command itself needs specific shell handling.
            // Using cmd /c explicitly often helps.
            process = Runtime.getRuntime().exec(command);
        } else {
            // For Unix-like systems, Runtime.exec(String) is generally fine for simple commands
            // but for commands with arguments or shell features, it's better to use
            // Runtime.exec(String[]) or ProcessBuilder.
            // For this simulation, we assume 'xdg-open' or 'cat' are simple enough.
            process = Runtime.getRuntime().exec(command);
        }


        // Read output (optional, but good practice for debugging)
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }

        // Read error output
        try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = errorReader.readLine()) != null) {
                System.err.println("ERROR: " + line);
            }
        }

        // Wait for the process to complete and get its exit code
        int exitCode = process.waitFor();
        System.out.println("Command exited with code: " + exitCode);
        return exitCode;
    }

