     */
    public String evaluateExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return "Error: La expresión no puede estar vacía.";
        }

        // Lista de palabras clave y patrones peligrosos (case-insensitive)
        // Esto es una medida de seguridad básica; para aplicaciones críticas, se requiere un parser más robusto.
        String[] dangerousKeywords = {
            "System", "Runtime", "ProcessBuilder", "Class", "Object", "java", "import",
            "eval", "function", "var", "let", "const", "new", "this", "window", "document",
            "prototype", "constructor", "alert", "console", "require", "module", "global",
            "setTimeout", "setInterval", "XMLHttpRequest", "fetch", "Promise", "debugger"
        };

        // Sanitización básica: verificar si la expresión contiene palabras clave peligrosas
        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                return "Error: La expresión contiene palabras clave o patrones peligrosos no permitidos.";
            }
        }

        // Opcional: Permitir solo caracteres numéricos, operadores básicos y paréntesis.
