        if (engine == null) {
            return "Error: No se encontró un motor de script JavaScript. Asegúrate de que tu JRE lo soporte.";
        }

        try {
            // Evaluar la expresión
            Object result = engine.eval(expression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            // Capturar errores de sintaxis o ejecución del script
            return "Error de sintaxis o evaluación: " + e.getMessage();
        } catch (Exception e) {
            // Capturar cualquier otra excepción inesperada
            return "Error inesperado durante la evaluación: " + e.getMessage();
        }
    }
}
