    /**
     * 解析并评估用户的数学表达式。
     * 
     * 该函数通过阻止常见的危险关键词和非算术字符来限制表达式为基本算术。
     *
     * @param expression 用户输入的数学表达式字符串。
     * @return 表达式的计算结果，以 Double 形式返回。
     * @throws IllegalArgumentException 如果表达式包含不允许的字符、关键词或无法解析。
     */
    public Double evaluateMathExpression(String expression) throws IllegalArgumentException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Expression cannot be null or empty.");
        }

        // 1. 定义不允许的关键词（不区分大小写）
        // 这些关键词可能用于执行恶意代码或访问系统资源
        Set<String> forbiddenKeywords = new HashSet<>(Arrays.asList(
            "import", "java", "script", "runtime", "process", "file", "os", "system",
            "class", "package", "function", "var", "let", "const", "new", "eval",
            "while", "for", "if", "else", "try", "catch", "throw", "return", "this",
            "window", "document", "alert", "prompt", "confirm", "setTimeout", "setInterval",
            "XMLHttpRequest", "fetch", "require", "module", "global", "console", "debugger",
            "prototype", "constructor", "call", "apply", "bind", "with", "yield", "async", "await"
        ));

        // 2. 检查表达式是否包含任何不允许的关键词
        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("Expression contains forbidden keyword: " + keyword);
            }
        }

        // 3. 严格的字符白名单检查
        // 只允许数字 (0-9), 小数点 (.), 基本运算符 (+, -, *, /), 括号 ((, )), 和空格
        // 任何其他字符都将被视为非法
        Pattern allowedCharsPattern = Pattern.compile("^[0-9+\\-*/().\\s]+$");
        if (!allowedCharsPattern.matcher(expression).matches()) {
            // 找出第一个不允许的字符以提供更具体的错误信息
            Pattern disallowedCharPattern = Pattern.compile("[^0-9+\\-*/().\\s]");
            Matcher matcher = disallowedCharPattern.matcher(expression);
            if (matcher.find()) {
                throw new IllegalArgumentException("Expression contains disallowed character: '" + matcher.group() + "'");
            } else {
                // Fallback for unexpected cases
                throw new IllegalArgumentException("Expression contains disallowed characters or invalid structure.");
            }
        }

        // 4. 额外的安全检查：防止连续的运算符或不合法的点号使用
        // 避免 "++", "--", "**", "//", ".*", "/.", ".+" 等
        // 允许 "1.2", "-1.2", ".5" (JavaScript 引擎通常支持)
        if (Pattern.compile("[+\\-*/.]{2,}").matcher(expression).find()) {
             throw new IllegalArgumentException("Expression contains invalid sequence of operators or dots.");
        }
        // 避免表达式以运算符或点号开头或结尾 (除了负数)
        if (Pattern.compile("^[*/.)]").matcher(expression.trim()).find() ||
            Pattern.compile("[+\\-*/.(]$").matcher(expression.trim()).find()) {
            throw new IllegalArgumentException("Expression starts or ends with an invalid character.");
        }


        // 5. 使用 JavaScript 引擎评估表达式
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            throw new IllegalStateException("JavaScript engine not found. Ensure JRE is configured correctly.");
        }

        try {
            Object result = engine.eval(expression);

            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                // 如果结果不是数字，可能表示表达式评估出了问题
                throw new IllegalArgumentException("Expression evaluation resulted in a non-numeric value.");
            }
        } catch (ScriptException e) {
            // 捕获脚本执行错误，并包装为 IllegalArgumentException
            throw new IllegalArgumentException("Failed to evaluate expression: " + e.getMessage(), e);
        } catch (Exception e) {
            // 捕获其他潜在的运行时错误
            throw new IllegalArgumentException("An unexpected error occurred during expression evaluation: " + e.getMessage(), e);
        }
    }
}
