import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Parse en evalueer 'n wiskundige uitdrukking van die gebruiker.
     * 
     * Die funksie beperk die uitdrukking tot basiese rekenkunde deur algemene gevaarlike sleutelwoorde te blokkeer.
     *
     * @param expression Die wiskundige uitdrukking as 'n string (bv. "2 + 3 * 4").
     * @return Die resultaat van die evaluering van die uitdrukking as 'n Object.
     * @throws IllegalArgumentException As die uitdrukking 'n verbode sleutelwoord bevat.
     * @throws ScriptException As daar 'n fout is tydens die evaluering van die uitdrukking.
     * @throws IllegalStateException As 'n geskikte ScriptEngine nie gevind kan word nie.
     */
    public Object evaluateMathematicalExpression(String expression) throws IllegalArgumentException, ScriptException, IllegalStateException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("Die uitdrukking kan nie leeg wees nie.");
        }

        // Lys van gevaarlike sleutelwoorde wat geblokkeer moet word
        // Hierdie woorde kan gebruik word om Java-objekte te skep, toegang tot die stelsel te verkry, ens.
        String[] dangerousKeywords = {
            "java", "javax", "import", "new", "System", "Runtime", "Class", "Process", "File",
            "eval", "function", "var", "const", "let", "while", "for", "if", "else",
            "throw", "try", "catch", "finally", "return", "void", "null", "undefined"
        };

        String lowerCaseExpression = expression.toLowerCase();

        // Kontroleer vir gevaarlike sleutelwoorde
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                throw new IllegalArgumentException("Die uitdrukking bevat 'n verbode sleutelwoord: '" + keyword + "'");
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        // Gebruik die JavaScript-enjin vir wiskundige evaluering
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            throw new IllegalStateException("Geen JavaScript ScriptEngine gevind nie. Maak seker dat 'n JRE met Nashorn of GraalJS beskikbaar is.");
        }

        // Evalueer die uitdrukking
        // Die ScriptEngine sal die string as 'n JavaScript-uitdrukking interpreteer en die resultaat teruggee.
        return engine.eval(expression);
    }

    // Voorbeeld van hoe om die funksie te gebruik
    public static void main(String[] args) {
        ClassX parser = new ClassX();

        // Geldige uitdrukkings
        String[] validExpressions = {
            "2 + 3 * 4",
            "(10 - 5) / 2",
            "Math.pow(2, 3)", // Let wel: Math.pow is 'n standaard JavaScript funksie en word nie geblokkeer deur ons huidige sleutelwoordlys nie.
                              // As dit ook geblokkeer moet word, moet 'Math' by die dangerousKeywords gevoeg word.
            "100 / 5 + 7",
            "2.5 * 4.1"
        };

        System.out.println("--- Geldige Uitdrukkings ---");
        for (String expr : validExpressions) {
            try {
                Object result = parser.evaluateMathematicalExpression(expr);
                System.out.println("Uitdrukking: \"" + expr + "\" = " + result + " (Tipe: " + result.getClass().getName() + ")");
            } catch (Exception e) {
                System.err.println("Fout met uitdrukking \"" + expr + "\": " + e.getMessage());
            }
        }

        // Ongeldige uitdrukkings (met gevaarlike sleutelwoorde of sintaksfoute)
        String[] invalidExpressions = {
            "System.exit(0)",
            "new java.io.File('test.txt')",
            "importPackage(java.lang)",
            "var x = 10; x * 2;",
            "function add(a,b){return a+b;}",
            "2 + 3 * for", // Sintaksfout
            "", // Leë uitdrukking
            "null + 5"
        };

        System.out.println("\n--- Ongeldige Uitdrukkings ---");
        for (String expr : invalidExpressions) {
            try {
                Object result = parser.evaluateMathematicalExpression(expr);
                System.out.println("Uitdrukking: \"" + expr + "\" = " + result);
            } catch (Exception e) {
                System.err.println("Fout met uitdrukking \"" + expr + "\": " + e.getMessage());
            }
        }
    }
}
