            " " + "net.", " " + "org.", " " + "script", " " + "engine", " " + "manager",
            " " + "bindings", " " + "context", " " + "host", " " + "global", " " + "scope",
            " " + "print", " " + "alert", " " + "confirm", " " + "prompt", " " + "document",
            " " + "window", " " + "location", " " + "history", " " + "navigator",
            " " + "setTimeout", " " + "setInterval", " " + "clearInterval", " " + "clearTimeout"
        };

        // Normalize expression for keyword checking (e.g., remove spaces around operators)
        // This helps catch keywords even if they are spaced out.
        String normalizedExpression = expression.toLowerCase()
                                                .replaceAll("\\s+", " ") // Replace multiple spaces with single space
                                                .replaceAll("([+\\-*/%^()])", " $1 ") // Add spaces around operators/parentheses
                                                .trim();

        for (String keyword : disallowedKeywords) {
            if (normalizedExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Expression contains disallowed keyword: " + keyword.trim());
