                // for valid-looking arithmetic (e.g., if it evaluates to a string "NaN" or "Infinity")
                try {
                    return Double.parseDouble(result.toString());
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Expression did not evaluate to a valid number: " + result, e);
                }
            }
        } catch (ScriptException e) {
            // Catch specific script evaluation errors (e.g., syntax errors)
            throw new IllegalArgumentException("Error evaluating mathematical expression: " + e.getMessage(), e);
        } catch (Exception e) {
            // Catch any other unexpected errors during evaluation
            throw new IllegalArgumentException("An unexpected error occurred during expression evaluation: " + e.getMessage(), e);
        }
    }
