import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Jäsentää ja arvioi käyttäjän antaman matemaattisen lausekkeen.
     * 
     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     * 
     * @param expression Käyttäjän antama matemaattinen lauseke merkkijonona.
     * @return Lausekkeen arvioitu tulos Double-muodossa.
     * @throws IllegalArgumentException Jos lauseke sisältää kiellettyjä avainsanoja tai on virheellinen.
     */
    public double evaluate(String expression) {
        // Lista kielletyistä avainsanoista, jotka estävät koodin injektion tai monimutkaiset toiminnot.
        String[] forbiddenKeywords = {
            "System", "Runtime", "Process", "File", "Class", "Object", "Thread",
            "import", "new", "eval", "exec", "function", "var", "let", "const",
            "while", "for", "if", "else", "try", "catch", "throw", "return",
            "package", "java", "javax", "net", "io", "reflect", "util", "security"
        };

        // Tarkista lauseke kiellettyjen avainsanojen varalta.
        for (String keyword : forbiddenKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Lauseke sisältää kielletyn avainsanan: " + keyword);
            }
        }

        // Poista kaikki merkit paitsi numerot, operaattorit (+-*/%) ja desimaalipisteet.
        // Tämä auttaa estämään monimutkaisempia hyökkäyksiä, jotka eivät välttämättä käytä avainsanoja.
        String cleanedExpression = expression.replaceAll("[^0-9+\\-*/%.()]", "");

        // Varmista, että puhdistettu lauseke ei ole tyhjä
        if (cleanedExpression.trim().isEmpty()) {
            throw new IllegalArgumentException("Lauseke on tyhjä tai sisältää vain kiellettyjä merkkejä.");
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Käytä JavaScript-moottoria arviointiin

        try {
            // Arvioi lauseke.
            // Huom: Vaikka avainsanoja on rajoitettu ja merkkejä puhdistettu,
            // ScriptEngine voi silti olla turvallisuusriski, jos rajoitukset ovat puutteelliset.
            // Tämä toteutus pyrkii minimoimaan riskin perusaritmetiikan osalta.
            Object result = engine.eval(cleanedExpression);

            // Tarkista, että tulos on numeerinen.
            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                throw new IllegalArgumentException("Lausekkeen tulos ei ollut numeerinen.");
            }
        } catch (ScriptException e) {
            // Sieppaa virheet, jotka johtuvat virheellisestä syntaksista tai muista arviointiongelmista.
            throw new IllegalArgumentException("Virhe lausekkeen arvioinnissa: " + e.getMessage(), e);
        } catch (Exception e) {
            // Sieppaa muut odottamattomat virheet.
            throw new IllegalArgumentException("Odottamaton virhe lausekkeen käsittelyssä: " + e.getMessage(), e);
        }
    }
}
