import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Elemzi és értékeli a felhasználótól származó matematikai kifejezést.
     * <p>
     * A függvény korlátozza a kifejezést az alapvető aritmetikára azáltal, hogy blokkolja a
     * gyakori veszélyes kulcsszavakat.
     *
     * @param expression A felhasználó által megadott matematikai kifejezés.
     * @return Az kifejezés kiértékelt eredménye, vagy null, ha hiba történt.
     * @throws IllegalArgumentException Ha a kifejezés érvénytelen karaktereket vagy blokkolt kulcsszavakat tartalmaz.
     */
    public Double evaluateMathExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("A kifejezés nem lehet üres.");
        }

        // Tisztítás és érvényesítés
        String cleanedExpression = expression.trim();

        // Engedélyezett karakterek: számok, +, -, *, /, %, (, ), szóköz
        if (!cleanedExpression.matches("^[0-9+\\-*/%().\\s]+$")) {
            throw new IllegalArgumentException("A kifejezés érvénytelen karaktereket tartalmaz.");
        }

        // Veszélyes kulcsszavak blokkolása
        String[] dangerousKeywords = {"System", "Runtime", "Process", "Class", "Object", "java", "javax", "import", "eval", "exec", "new", "function", "var", "const", "let", "while", "for", "if", "else", "try", "catch", "throw", "return"};
        for (String keyword : dangerousKeywords) {
            // Case-inszenzitív ellenőrzés és szóhatárok figyelembe vétele
            if (cleanedExpression.matches("(?i).*\\b" + keyword + "\\b.*")) {
                throw new IllegalArgumentException("A kifejezés blokkolt kulcsszót tartalmaz: " + keyword);
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Vagy "Nashorn" régebbi JDK-k esetén

        if (engine == null) {
            // Fallback, ha a JavaScript motor nem található (pl. moduláris JDK-ban hiányzik a nashorn)
            // Ebben az esetben egy saját parser/evaluátor kellene, vagy hiba dobása.
            System.err.println("Figyelem: A JavaScript ScriptEngine nem található. A kifejezés kiértékelése nem lehetséges.");
            return null;
        }

        try {
            Object result = engine.eval(cleanedExpression);
            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                // Ha az eredmény nem szám, az valószínűleg hiba vagy nem várt viselkedés
                System.err.println("A kifejezés kiértékelése nem számot eredményezett: " + result);
                return null;
            }
        } catch (ScriptException e) {
            throw new IllegalArgumentException("Hiba történt a kifejezés kiértékelése során: " + e.getMessage(), e);
        } catch (Exception e) {
            // Egyéb futásidejű hibák
            throw new RuntimeException("Váratlan hiba történt a kifejezés kiértékelése során: " + e.getMessage(), e);
        }
    }
