public class ClassX {
    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     *
     * @param input The user input string to sanitize.
     * @return The sanitized string with script tags removed. Returns null if the input is null.
     */
    public String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }

        // Remove opening <script> tags, including any attributes (case-insensitive)
        // (?i) makes the regex case-insensitive
        // <script\\b[^>]*> matches <script, followed by a word boundary,
        // then any characters that are not '>', zero or more times, until the closing >
        String sanitized = input.replaceAll("(?i)<script\\b[^>]*>", "");

        // Remove closing </script> tags (case-insensitive)
        sanitized = sanitized.replaceAll("(?i)</script>", "");

        return sanitized;
    }
}
