import java.util.regex.Pattern;

public class ClassX {
    /**
     * 通过移除脚本标签来清理用户输入。
     * 
     * 该函数使用字符串替换来去除 <script> 标签及其内容。
     * 它处理大小写不敏感的标签、标签内的属性以及多行脚本内容。
     *
     * @param input 用户输入的字符串
     * @return 清理后的字符串，移除了所有 <script> 标签及其内部内容
     */
    public String cleanInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // 1. 移除完整的 <script>...</script> 块
        // (?i) 开启大小写不敏感匹配
        // <script\\b[^>]*> 匹配开头的 <script 标签，允许有属性
        // [\\s\\S]*? 匹配标签内的所有内容（包括换行符），非贪婪模式
        // <\\/script> 匹配闭合的 </script> 标签
        String cleanedInput = input.replaceAll("(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>", "");

        // 2. 移除任何可能遗留的未闭合的 <script> 标签
        // 例如：<script src="malicious.js"> 或 <script>
        cleanedInput = cleanedInput.replaceAll("(?i)<script\\b[^>]*>", "");

        // 3. 移除任何可能遗留的未匹配的 </script> 标签
        // 例如：</script>
        cleanedInput = cleanedInput.replaceAll("(?i)<\\/script>", "");

        return cleanedInput;
    }
}
```

