import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    /**
     * A constant to determine if the application is running in a production environment.
     * This can be set via a system property, e.g., -Dapp.env.production=true.
     * Defaults to false if the property is not set or is not "true".
     */
    private static final boolean IS_PRODUCTION_ENVIRONMENT = 
        Boolean.parseBoolean(System.getProperty("app.env.production", "false"));

    /**
     * Returns debug information for a given {@link Throwable}.
     * 
     * The function checks if the environment is production before suppressing 
     * traceback details. In a production environment, only the error type and message
     * are included, with a note that the traceback is suppressed. In non-production
     * environments, the full stack trace is included.
     * 
     * @param throwable The {@link Throwable} object for which to generate debug information.
     *                  If null, a general debug message is returned.
     * @return A string containing formatted debug information.
     */
    public String getDebugInformation(Throwable throwable) {
        StringBuilder debugInfo = new StringBuilder();
        debugInfo.append("--- Application Debug Information ---\n");
        debugInfo.append("Timestamp: ").append(System.currentTimeMillis()).append("\n");
        debugInfo.append("Environment: ").append(IS_PRODUCTION_ENVIRONMENT ? "Production" : "Development/Test").append("\n");

        if (throwable != null) {
            debugInfo.append("Error Type: ").append(throwable.getClass().getName()).append("\n");
            debugInfo.append("Error Message: ").append(throwable.getMessage()).append("\n");

            if (IS_PRODUCTION_ENVIRONMENT) {
                debugInfo.append("Traceback: Suppressed in production environment for security and brevity.\n");
            } else {
                debugInfo.append("Traceback:\n");
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                throwable.printStackTrace(pw);
                debugInfo.append(sw.toString());
            }
        } else {
            debugInfo.append("No specific error provided.\n");
            if (!IS_PRODUCTION_ENVIRONMENT) {
                debugInfo.append("Current Call Stack (no error, for context):\n");
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                new Throwable().printStackTrace(pw); // Get current stack trace
                debugInfo.append(sw.toString());
            }
        }
        debugInfo.append("-------------------------------------\n");
        return debugInfo.toString();
    }
}
