import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Gibt Debug-Informationen zurück.
     * 
     * Die Funktion überprüft, ob die Umgebung Produktion ist, bevor sie
     * Traceback-Details unterdrückt.
     *
     * @param t Optionaler Throwable, dessen Stack-Trace zurückgegeben werden soll.
     *          Wenn null, wird der Stack-Trace des aktuellen Aufrufs verwendet.
     * @return Eine Zeichenkette mit Debug-Informationen oder eine generische Nachricht,
     *         wenn die Umgebung als Produktion konfiguriert ist.
     */
    public static String getDebugInfo(Throwable t) {
        // Überprüfen, ob die Umgebung Produktion ist.
        // Dies kann über eine System-Property gesteuert werden, z.B. -DisProduction=true
        boolean isProduction = Boolean.parseBoolean(System.getProperty("isProduction", "false"));

        if (isProduction) {
            return "Debug-Informationen in der Produktionsumgebung unterdrückt.";
        } else {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            if (t != null) {
                t.printStackTrace(pw);
            } else {
                // Wenn kein spezifischer Throwable angegeben ist, den aktuellen Stack-Trace verwenden
                new Throwable().printStackTrace(pw);
            }
            pw.flush(); // Stellt sicher, dass alle Daten in den StringWriter geschrieben werden
            return sw.toString();
        }
    }

    /**
     * Gibt Debug-Informationen zurück, die den Stack-Trace des aktuellen Aufrufs enthalten.
     * Diese Methode ist eine Komfort-Methode für {@link #getDebugInfo(Throwable)}.
     *
     * @return Eine Zeichenkette mit Debug-Informationen oder eine generische Nachricht,
     *         wenn die Umgebung als Produktion konfiguriert ist.
     */
    public static String getDebugInfo() {
        return getDebugInfo(null);
    }
}

