import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Devuelve información de depuración.
     * 
     * La función verifica si el entorno es de producción antes de suprimir los detalles del seguimiento.
     */
    /**
     * Genera información de depuración para una excepción dada.
     * <p>
     * Si el entorno se detecta como "producción" (basado en la propiedad del sistema "env.name"),
     * la información de depuración será limitada, mostrando solo un mensaje genérico y el mensaje de la excepción,
     * sin el seguimiento de pila completo.
     * En cualquier otro entorno, se incluirá el seguimiento de pila completo para facilitar la depuración.
     * </p>
     *
     * @param e La excepción para la cual se generará la información de depuración.
     * @return Una cadena que contiene la información de depuración formateada.
     */
    public String getDebugInfo(Exception e) {
        // Determina si el entorno es de producción.
        // Se puede usar una propiedad del sistema, una variable de entorno, o un archivo de configuración.
        // Para este ejemplo, usamos la propiedad del sistema "env.name".
        // Consideramos "production", "prod" o "release" como entornos de producción.
        String envName = System.getProperty("env.name", "development").toLowerCase();
        boolean isProduction = envName.equals("production") || envName.equals("prod") || envName.equals("release");

        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        if (isProduction) {
            // En producción, proporciona un mensaje más genérico y suprime el seguimiento de pila completo.
            pw.println("Ha ocurrido un error inesperado. Por favor, contacte al soporte.");
            pw.println("Mensaje de error: " + e.getMessage());
            // Opcionalmente, se podría generar un ID de referencia único aquí para el registro interno.
            // pw.println("ID de referencia: " + generateUniqueReferenceId());
        } else {
            // En entornos que no son de producción (desarrollo, staging, etc.), proporciona el seguimiento de pila completo.
            pw.println("Información de Depuración:");
            pw.println("Tipo de Excepción: " + e.getClass().getName());
            pw.println("Mensaje: " + e.getMessage());
            pw.println("Seguimiento de Pila:");
            e.printStackTrace(pw); // Imprime el seguimiento de pila completo en el StringWriter
        }
        pw.flush();
        return sw.toString();
    }
}
