        boolean isProduction = "true".equalsIgnoreCase(System.getProperty("env.production"));

        if (isProduction) {
            // In ambiente di produzione, restituisce un messaggio generico per evitare di esporre dettagli sensibili.
            return "An unexpected error occurred. Please contact support with the incident ID if available.";
        } else {
            // In ambiente non di produzione (sviluppo/test), restituisce lo stack trace completo.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            return sw.toString();
        }
    }
}
