import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    // Flag to indicate if the application is running in a production environment.
    // Default to false (non-production) for safer development.
    private static boolean isProductionEnvironment = false;

    /**
     * Sets the production environment flag for the application.
     * When set to {@code true}, {@link #getDebugInfo(Throwable)} will return
     * a generic error message instead of a detailed stack trace.
     *
     * @param isProduction {@code true} if the environment is production; {@code false} otherwise.
     */
    public static void setProductionEnvironment(boolean isProduction) {
        ClassX.isProductionEnvironment = isProduction;
    }

    /**
     * Retorna informações de depuração.
     *
     * A função verifica se o ambiente é de produção antes de suprimir os detalhes do traceback.
     * Se o ambiente for de produção (determinado pelo flag {@code isProductionEnvironment}),
     * uma mensagem de erro genérica é retornada para evitar a exposição de detalhes internos.
     * Caso contrário, o stack trace completo da exceção fornecida é retornado.
     *
     * @param throwable A exceção ou erro para o qual as informações de depuração são solicitadas.
     * @return Uma {@code String} contendo as informações de depuração (stack trace completo em não-produção,
     *         ou uma mensagem genérica em produção).
     */
    public static String getDebugInfo(Throwable throwable) {
        if (isProductionEnvironment) {
            // In a production environment, return a generic error message
            return "Ocorreu um erro inesperado. Por favor, tente novamente mais tarde ou entre em contato com o suporte técnico. (Ref: " + System.currentTimeMillis() + ")";
        } else {
            // In a non-production environment, return the full stack trace
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            pw.flush(); // Ensure all content is written to StringWriter
            return sw.toString();
        }
    }
}
