            StringBuilder sb = new StringBuilder();
            sb.append("Exception: ").append(t.getClass().getName());
            if (t.getMessage() != null && !t.getMessage().isEmpty()) {
                sb.append(" - ").append(t.getMessage());
            }

            // Optionally, add the root cause message
