public class ClassX {

    // Determines if the application is running in a production environment.
    // This can be configured via system properties, environment variables,
    // or a dedicated configuration service in a real-world application.
    // For this example, it checks a system property "env". If "env" is "prod"
    // (case-insensitive), it's considered production. Defaults to non-production.
    private static final boolean IS_PRODUCTION_ENVIRONMENT =
            System.getProperty("env", "dev").equalsIgnoreCase("prod");

    /**
     * 返回调试信息。
     *
     * 该函数在抑制回溯细节之前检查环境是否为生产环境。
     * 如果是生产环境，它将返回简化的错误信息，以避免暴露敏感的系统细节。
     * 如果是非生产环境（如开发或测试），它将返回完整的堆栈跟踪。
     *
     * @param t 导致需要调试信息的 Throwable 对象。如果为 null，则返回相应的提示信息。
     * @return 包含调试信息的字符串。
     */
    public static String getDebugInformation(Throwable t) {
        if (t == null) {
            return "No throwable object provided for debug information.";
        }

        if (IS_PRODUCTION_ENVIRONMENT) {
            // In a production environment, return minimal information.
            // This prevents exposing internal system details or overwhelming logs.
            return "An unexpected error occurred. Error type: " + t.getClass().getSimpleName() +
                   ". Message: " + (t.getMessage() != null ? t.getMessage() : "No specific message.");
        } else {
            // In non-production environments (development, testing),
            // provide the full stack trace for detailed debugging.
            StringWriter sw = new StringWriter();
