     */
    public static String getDebugInfo(Throwable throwable) {
        if (isProductionEnvironment()) {
            // In production, return a generic error message or just the exception message
            return "An unexpected error occurred. Please contact support. Error ID: " + throwable.getClass().getSimpleName();
        } else {
            // In non-production, return the full stack trace
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }

