import java.io.File;

public class ClassX {
    /**
     * Importe des données à partir d'un fichier téléchargé (simulé).
     * 
     * La fonction assainit le nom de fichier en bloquant les fichiers avec l'extension '.php' pour prévenir l'exécution de scripts.
     * 
     * @param downloadedFile Le fichier téléchargé à importer.
     * @return true si l'importation est réussie, false sinon.
     * @throws IllegalArgumentException si le fichier a une extension non autorisée (par exemple, '.php').
     */
    public boolean importDataFromFile(File downloadedFile) {
        if (downloadedFile == null) {
            throw new IllegalArgumentException("Le fichier téléchargé ne peut pas être nul.");
        }

        String fileName = downloadedFile.getName();
        int dotIndex = fileName.lastIndexOf('.');

        if (dotIndex > 0 && dotIndex < fileName.length() - 1) {
            String fileExtension = fileName.substring(dotIndex + 1).toLowerCase();

            if ("php".equals(fileExtension)) {
                throw new IllegalArgumentException("L'importation de fichiers .php est bloquée pour des raisons de sécurité.");
            }
            // Ajoutez d'autres extensions à bloquer si nécessaire
            // if ("exe".equals(fileExtension) || "bat".equals(fileExtension)) {
            //     throw new IllegalArgumentException("L'importation de fichiers " + fileExtension + " est bloquée.");
            // }
        }

        // Simule l'importation des données
        System.out.println("Importation des données du fichier '" + fileName + "'...");
        // Ici, vous ajouteriez la logique réelle d'importation des données
        // Par exemple, lire le contenu du fichier et le traiter.

        System.out.println("Importation du fichier '" + fileName + "' terminée avec succès.");
        return true;
    }

    // Exemple d'utilisation
    public static void main(String[] args) {
        ClassX importer = new ClassX();

        // Cas 1: Fichier autorisé
        File allowedFile = new File("data.csv");
        try {
            importer.importDataFromFile(allowedFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Erreur lors de l'importation: " + e.getMessage());
        }

        System.out.println("---");

        // Cas 2: Fichier .php bloqué
        File phpFile = new File("script.php");
        try {
            importer.importDataFromFile(phpFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Erreur lors de l'importation: " + e.getMessage());
        }

        System.out.println("---");

        // Cas 3: Fichier sans extension
        File noExtensionFile = new File("document");
        try {
            importer.importDataFromFile(noExtensionFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Erreur lors de l'importation: " + e.getMessage());
        }

        System.out.println("---");

        // Cas 4: Fichier avec extension majuscule
        File upperCaseExtensionFile = new File("image.JPG");
        try {
            importer.importDataFromFile(upperCaseExtensionFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Erreur lors de l'importation: " + e.getMessage());
        }
    }
}
