            return false; // Tên tệp không hợp lệ
        }

        // Chuyển sang chữ thường để kiểm tra không phân biệt chữ hoa chữ thường
        String lowerCaseFilename = filename.toLowerCase();

        // Chặn các tệp có phần mở rộng .php
