            System.out.println("ERROR: Empty filename should have been blocked.");
        } catch (IllegalArgumentException e) {
            System.out.println("Caught expected error for empty filename: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Caught unexpected error for empty filename: " + e.getMessage());
