import java.io.File;

public class ClassX {
    /**
     * Laai data vanaf 'n opgelaaide lêer (Simuleer).
     * 
     * Die funksie saniteer die lêernaam deur lêers met die '.php' uitbreiding te blokkeer om die uitvoering van skripte te voorkom.
     *
     * @param filename Die naam van die lêer wat gelaai moet word.
     * @return 'n String wat die suksesvolle laai van die lêer aandui.
     * @throws IllegalArgumentException As die lêernaam null, leeg is, of eindig met '.php' (geval-onsensitief).
     */
    public String loadDataFromFile(String filename) {
        if (filename == null || filename.trim().isEmpty()) {
            throw new IllegalArgumentException("Lêernaam kan nie leeg wees nie.");
        }

        // Saniteer die lêernaam deur lêers met die '.php' uitbreiding te blokkeer
        if (filename.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("Onwettige lêertipe: PHP-lêers word nie toegelaat nie om die uitvoering van skripte te voorkom.");
        }

        // Simuleer die laai van data
        // In 'n regte toepassing sou hier logika wees om die lêer te lees en te verwerk.
        return "Data suksesvol gelaai vanaf '" + filename + "'. (Simulasie)";
    }

    // 'n Hoofmetode vir toetsing (opsioneel)
    public static void main(String[] args) {
        ClassX processor = new ClassX();

        // Geldige lêernaam
        try {
            System.out.println(processor.loadDataFromFile("document.txt"));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Nog 'n geldige lêernaam
        try {
            System.out.println(processor.loadDataFromFile("image.jpg"));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Ongeldige lêernaam (PHP)
        try {
            System.out.println(processor.loadDataFromFile("script.php"));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Ongeldige lêernaam (PHP, hoofletters)
        try {
            System.out.println(processor.loadDataFromFile("malicious.PHP"));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Lêernaam wat PHP bevat, maar nie eindig met .php nie
        try {
            System.out.println(processor.loadDataFromFile("myphpfile.txt"));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Leë lêernaam
        try {
            System.out.println(processor.loadDataFromFile(""));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }

        // Null lêernaam
        try {
            System.out.println(processor.loadDataFromFile(null));
        } catch (IllegalArgumentException e) {
            System.err.println("Fout: " + e.getMessage());
        }
    }
}
