     * 
     * @param filename İşlenecek dosyanın adı.
     * @return Dosyadan alınan simüle edilmiş veri.
     * @throws IllegalArgumentException Eğer dosya adı '.php' uzantısına sahipse.
     */
    public String getDataFromFile(String filename) {
        if (filename == null || filename.trim().isEmpty()) {
            throw new IllegalArgumentException("Dosya adı boş olamaz.");
        }

        // Dosya adını temizle ve '.php' uzantısını engelle
        if (filename.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("'.php' uzantılı dosyalara izin verilmez: " + filename);
        }

        // Güvenli bir dosya adı oluştur (örneğin, yol ayırıcılarını normalleştir)
        // Bu simülasyon için, sadece uzantı kontrolü yeterli olabilir.
        // Gerçek bir uygulamada, daha fazla yol temizleme ve güvenlik kontrolü yapılmalıdır.
        String cleanedFilename = filename.replace("..", "").replace("/", "").replace("\\", "");
        if (!cleanedFilename.equals(filename)) {
             // Eğer temizleme işlemi dosya adını değiştirdiyse, bu durumu ele alabiliriz.
             // Bu örnekte, sadece uyarı verip temizlenmiş adı kullanıyoruz.
             System.out.println("Uyarı: Dosya adı temizlendi. Orijinal: '" + filename + "', Temizlenmiş: '" + cleanedFilename + "'");
        }


        // Burada, gerçek bir dosya okuma işlemi yerine simüle edilmiş bir veri döndürülür.
        // Örneğin, dosya adına göre farklı bir içerik döndürülebilir.
        return "Simüle edilmiş veri: '" + cleanedFilename + "' dosyasından başarıyla alındı.";
    }

    public static void main(String[] args) {
        ClassX processor = new ClassX();

        // Geçerli bir dosya adı ile test
        try {
            System.out.println(processor.getDataFromFile("document.txt"));
            System.out.println(processor.getDataFromFile("image.jpg"));
            System.out.println(processor.getDataFromFile("report.pdf"));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }

        System.out.println("\n--- Güvenlik Kontrolü Testleri ---");

        // '.php' uzantılı dosya adı ile test
        try {
            System.out.println(processor.getDataFromFile("script.php"));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }

        // Büyük harfli '.PHP' uzantılı dosya adı ile test
        try {
            System.out.println(processor.getDataFromFile("exploit.PHP"));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }

        // Boş dosya adı ile test
        try {
            System.out.println(processor.getDataFromFile(""));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }

        // Null dosya adı ile test
        try {
            System.out.println(processor.getDataFromFile(null));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }

        // Yol manipülasyonu içeren dosya adı (temizleme mekanizması test)
        try {
            System.out.println(processor.getDataFromFile("../../../etc/passwd"));
        } catch (IllegalArgumentException e) {
            System.err.println("Hata: " + e.getMessage());
        }
    }
}
