        if (filename.toLowerCase().endsWith(".php")) {
            System.err.println("Security Alert: Ang pag-import ng PHP file ay hindi pinapayagan para sa kaligtasan: " + filename);
            return false;
        }

        // Dito ilalagay ang aktwal na lohika ng pag-import ng data
