     */
    public void importData(String filename) {
        if (filename == null || filename.trim().isEmpty()) {
            throw new IllegalArgumentException("Bestandsnaam kan niet leeg zijn.");
        }

        // Sanitize the filename: block .php extension
        if (filename.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("Bestanden met de '.php' extensie zijn niet toegestaan om scriptuitvoering te voorkomen.");
