        int keyLength = key.length;

        if (keyLength == 16) {
            algorithm = "AES";
        } else if (keyLength == 8) { // DES keys are typically 8 bytes
            algorithm = "DES";
        } else {
            throw new InvalidKeyException("Unsupported key length. Expected 16 bytes for AES or 8 bytes for DES.");
