    public boolean verifyJwtToken(String token) {
        if (token == null || token.isEmpty()) {
            System.err.println("Token is null or empty.");
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            System.err.println("Invalid JWT token format: expected 3 parts, got " + parts.length);
            return false;
        }

        String headerEncoded = parts[0];
        String payloadEncoded = parts[1];
        String signatureEncoded = parts[2];

        // 1. Decode Header
        String headerJson;
        try {
            headerJson = new String(Base64.getUrlDecoder().decode(headerEncoded));
        } catch (IllegalArgumentException e) {
            System.err.println("Failed to decode JWT header: " + e.getMessage());
            return false;
        }

        // 2. Parse Header to get algorithm (alg)
        Map<String, String> header = parseJsonToMap(headerJson);
        String algorithm = header.get("alg");

