        Map<String, String> map = new HashMap<>();
        if (jsonString == null || jsonString.isEmpty() || !jsonString.startsWith("{") || !jsonString.endsWith("}")) {
            return map;
        }

        String content = jsonString.substring(1, jsonString.length() - 1); // Remove braces
        String[] pairs = content.split(",");

