import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces.
     *
     * @param header The HTTP header string to parse and validate.
     * @return The original header string if it passes validation.
     * @throws IllegalArgumentException If the header is null, empty, or does not
     *                                  conform to the specified format (only
     *                                  alphanumeric characters and spaces).
     */
    public String parseHttpHeader(String header) throws IllegalArgumentException {
        if (header == null) {
            throw new IllegalArgumentException("HTTP header cannot be null.");
        }

        // Trim to handle headers that are just whitespace, then check if empty
        String trimmedHeader = header.trim();
        if (trimmedHeader.isEmpty()) {
            throw new IllegalArgumentException("HTTP header cannot be empty or contain only whitespace.");
        }

        // Regex: ^[a-zA-Z0-9 ]+$
        // ^        - asserts position at the start of the string
        // [a-zA-Z0-9 ] - matches any letter (uppercase or lowercase), any digit, or a space
        // +        - matches the previous token one or more times
        // $        - asserts position at the end of the string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(trimmedHeader);

        if (matcher.matches()) {
            return header; // Return the original header string if valid
        } else {
            throw new IllegalArgumentException(
                "Invalid HTTP header format. Header must contain only alphanumeric characters and spaces. " +
                "Received: '" + header + "'"
            );
        }
    }
}
