    public void redirectToTargetUrl(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("Target URL cannot be null or empty.");
        }

        URL urlObject;
        try {
            urlObject = new URL(targetUrl);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid target URL format: " + targetUrl, e);
        }

        String host = urlObject.getHost();
        if (host == null || host.isEmpty()) {
            // A URL without a host (e.g., "file:///path/to/file") might be problematic
            // or indicate an internal resource. For simplicity, we'll disallow it for external redirects.
            throw new IllegalArgumentException("Target URL does not specify a host: " + targetUrl);
        }

        // Check against the blacklist
        if (isDomainBlacklisted(host)) {
            // Log the attempt for security monitoring
            System.err.println("Attempted redirect to blacklisted domain: " + host + " from URL: " + targetUrl);
            throw new IllegalArgumentException("Redirect to blacklisted domain is not allowed.");
        }

        // If not blacklisted, perform the redirect
        response.sendRedirect(targetUrl);
    }

