     * 检查给定的域名是否在黑名单中。
     * 支持简单的子域名匹配（例如，如果 "example.com" 被列入黑名单，"sub.example.com" 也将被视为黑名单）。
     *
     * @param domain 要检查的域名。
     * @return 如果域名或其父域名在黑名单中，则返回 true；否则返回 false。
     */
    private boolean isDomainBlacklisted(String domain) {
        if (domain == null || domain.isEmpty()) {
            return false;
        }

        // Check exact match
        if (BLACKLISTED_DOMAINS.contains(domain)) {
            return true;
        }

        // Check for parent domains (e.g., if example.com is blacklisted, sub.example.com is also blacklisted)
        String currentDomain = domain;
        while (currentDomain.contains(".")) {
            int firstDotIndex = currentDomain.indexOf('.');
            currentDomain = currentDomain.substring(firstDotIndex + 1);
            if (BLACKLISTED_DOMAINS.contains(currentDomain)) {
                return true;
            }
        }
        return false;
    }

