public class ClassX {

    // Uma lista negra de domínios maliciosos conhecidos.
    // Em um ambiente de produção, esta lista seria gerenciada de forma mais robusta (ex: banco de dados, arquivo de configuração).
    private static final Set<String> BLACKLISTED_DOMAINS;

    static {
        Set<String> domains = new HashSet<>();
        domains.add("malicious-site.com");
        domains.add("phishing.example.org");
        domains.add("bad-domain.net");
        // Adicione outros domínios maliciosos conforme necessário
        BLACKLISTED_DOMAINS = Collections.unmodifiableSet(domains);
    }

    /**
     * Redireciona o usuário para uma URL de destino.
     * <p>
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     *
     * @param response   O objeto HttpServletResponse para realizar o redirecionamento.
     * @param targetUrl  A URL para a qual o usuário deve ser redirecionado.
     * @throws IOException Se ocorrer um erro de I/O durante o redirecionamento.
     * @throws IllegalArgumentException Se a URL de destino for nula, vazia ou apontar para um domínio na lista negra.
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("A URL de destino não pode ser nula ou vazia.");
        }

        // Valida o domínio da URL de destino
        if (isDomainBlacklisted(targetUrl)) {
            // Em um cenário real, você pode querer logar esta tentativa e/ou redirecionar para uma página de erro segura.
            throw new IllegalArgumentException("Tentativa de redirecionamento para um domínio na lista negra: " + targetUrl);
        }

        // Realiza o redirecionamento
        response.sendRedirect(targetUrl);
    }

    /**
     * Verifica se o domínio de uma dada URL está na lista negra.
     *
     * @param urlString A URL a ser verificada.
     * @return true se o domínio da URL estiver na lista negra, false caso contrário.
     */
    private boolean isDomainBlacklisted(String urlString) {
        try {
            URL url = new URL(urlString);
            String host = url.getHost();
            // Normaliza o host para comparação (ex: remove "www.")
            String normalizedHost = host.startsWith("www.") ? host.substring(4) : host;

            return BLACKLISTED_DOMAINS.contains(normalizedHost);
        } catch (MalformedURLException e) {
            // Se a URL for malformada, consideramos como um risco ou um erro,
            // e para fins de segurança, podemos optar por tratá-la como se estivesse na lista negra ou lançar uma exceção.
            // Aqui, vamos lançar uma exceção para indicar um problema com a URL fornecida.
            throw new IllegalArgumentException("A URL fornecida é malformada: " + urlString, e);
        }
    }
}
