     * אינסטנציה של אובייקטים.
     *
     * @param yamlString מחרוזת ה-YAML לטעינה.
     * @return אובייקט המייצג את הקונפיגורציה שנטענה.
     */
    public Object loadConfigFromString(String yamlString) {
        // יצירת LoaderOptions כדי להגביל את יכולות הבנאי
        LoaderOptions loaderOptions = new LoaderOptions();

        // מונע אינסטנציה של מחלקות באמצעות תגיות מפורשות כמו !!java.lang.Object
        // זהו מנגנון אבטחה קריטי למניעת deserialization של אובייקטים זדוניים.
        loaderOptions.setAllowClassConstructors(false);

