        // אם יש מחלקה ספציפית לקונפיגורציה (לדוגמה, MyConfig.class),
        // ניתן להשתמש ב: new Yaml(new Constructor(MyConfig.class, loaderOptions));
        // אחרת, Yaml עם LoaderOptions בלבד יטען למבנה גנרי (Map, List, String, וכו').
        Yaml yaml = new Yaml(loaderOptions);

        // טעינת הקונפיגורציה מהמחרוזת
        return yaml.load(yamlString);
    }
