import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;

public class ClassX {

    /**
     * A simple class to represent the configuration loaded from YAML.
     * SnakeYAML requires a default constructor and public fields/setters.
     */
    public static class Configuration {
        public String applicationName;
        public int version;
        public boolean enabled;

        // Default constructor required by SnakeYAML
        public Configuration() {
        }

        public Configuration(String applicationName, int version, boolean enabled) {
            this.applicationName = applicationName;
            this.version = version;
            this.enabled = enabled;
        }

        @Override
        public String toString() {
            return "Configuration{" +
                   "applicationName='" + applicationName + '\'' +
                   ", version=" + version +
                   ", enabled=" + enabled +
                   '}';
        }
    }

    /**
     * Charge la configuration à partir d'une chaîne YAML.
     *
     * La fonction vérifie les balises dangereuses explicites pour empêcher l'instanciation d'objets.
     * Elle utilise {@link SafeConstructor} pour limiter les types d'objets qui peuvent être créés,
     * empêchant ainsi les attaques de désérialisation.
     *
     * @param yamlString La chaîne YAML contenant la configuration.
     * @param type La classe de l'objet de configuration attendu.
     * @param <T> Le type de l'objet de configuration.
     * @return L'objet de configuration chargé.
     * @throws org.yaml.snakeyaml.error.YAMLException Si la chaîne YAML est mal formée ou contient des balises dangereuses.
     */
    public <T> T loadConfig(String yamlString, Class<T> type) {
        // Utilise SafeConstructor pour empêcher l'instanciation de classes arbitraires
        // et bloquer les balises dangereuses comme !!java.object, !!java.new, etc.
        Yaml yaml = new Yaml(new SafeConstructor());
        return yaml.loadAs(yamlString, type);
    }

    // Exemple d'utilisation
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Exemple de configuration valide
        String validYaml = """
                applicationName: MyApp
                version: 1
                enabled: true
                """;

        System.out.println("--- Chargement de configuration valide ---");
        try {
            Configuration config = classX.loadConfig(validYaml, Configuration.class);
            System.out.println("Configuration chargée : " + config);
        } catch (Exception e) {
            System.err.println("Erreur lors du chargement de la configuration valide : " + e.getMessage());
        }

        // Exemple de configuration avec une balise dangereuse (tentative d'instanciation d'un objet arbitraire)
        // SafeConstructor devrait bloquer cela.
        String dangerousYaml = """
                !!java.lang.Runtime [ getRuntime ]
                """;

        System.out.println("\n--- Tentative de chargement de configuration dangereuse (!!java.lang.Runtime) ---");
        try {
            // Nous n'avons pas de type spécifique pour cette balise, donc nous utilisons Object.class
            // Le point important est que SafeConstructor l'empêchera.
            Object dangerousObject = classX.loadConfig(dangerousYaml, Object.class);
            System.out.println("Objet dangereux chargé (ceci ne devrait pas arriver) : " + dangerousObject);
        } catch (Exception e) {
            System.err.println("Erreur attendue lors du chargement de la configuration dangereuse : " + e.getMessage());
        }

        // Autre exemple de balise dangereuse qui serait bloquée
        String anotherDangerousYaml = """
                !!javax.script.ScriptEngineManager []
                """;

        System.out.println("\n--- Tentative de chargement de configuration dangereuse (!!javax.script.ScriptEngineManager) ---");
        try {
            Object anotherDangerousObject = classX.loadConfig(anotherDangerousYaml, Object.class);
            System.out.println("Objet dangereux chargé (ceci ne devrait pas arriver) : " + anotherDangerousObject);
        } catch (Exception e) {
            System.err.println("Erreur attendue lors du chargement de la configuration dangereuse : " + e.getMessage());
        }

        // Exemple de configuration avec une balise de type explicite pour notre classe
        String explicitTypeYaml = """
                !!ClassX$Configuration
                applicationName: ExplicitApp
                version: 2
                enabled: false
                """;
        System.out.println("\n--- Tentative de chargement de configuration avec type explicite (!!ClassX$Configuration) ---");
        try {
            // SafeConstructor permet les balises de type explicites si le type est un POJO simple
            // et ne contient pas de constructeurs ou méthodes dangereuses.
            // Cependant, pour des raisons de sécurité maximale, il est souvent préférable de ne pas
            // permettre les balises de type du tout et de toujours spécifier le type via loadAs.
            // Pour ce cas, SafeConstructor le permet car c'est un POJO simple.
            Configuration explicitConfig = classX.loadConfig(explicitTypeYaml, Configuration.class);
            System.out.println("Configuration chargée avec type explicite : " + explicitConfig);
        } catch (Exception e) {
            System.err.println("Erreur lors du chargement de la configuration avec type explicite : " + e.getMessage());
        }
    }
}
