import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * Carrega a configuração a partir de uma string YAML.
     * 
     * A função verifica as tags perigosas explícitas para evitar a
     * instanciação de objetos.
     * 
     * @param yamlContent A string YAML contendo a configuração.
     * @param type A classe para a qual o YAML deve ser mapeado.
     * @param <T> O tipo da classe de configuração.
     * @return Um objeto da classe de configuração preenchido com os dados do YAML.
     * @throws YAMLException Se houver um erro ao analisar o YAML ou se tags perigosas forem encontradas.
     */
    public <T> T loadConfigFromYamlString(String yamlContent, Class<T> type) throws YAMLException {
        // Usa SafeConstructor para evitar a instanciação de objetos arbitrários
        // e restringir o uso de tags perigosas como !!java/object.
        // SafeConstructor é projetado para carregar dados YAML de forma segura,
        // permitindo apenas tipos básicos e coleções, e prevenindo a execução
        // de código arbitrário através de tags de tipo.
        Yaml yaml = new Yaml(new SafeConstructor());

        try {
            return yaml.loadAs(yamlContent, type);
        } catch (YAMLException e) {
            // Captura e relança a exceção para indicar um problema na análise do YAML
            // ou na detecção de tags perigosas.
            throw new YAMLException("Erro ao carregar a configuração YAML: " + e.getMessage(), e);
        }
    }
}
