import org.yaml.snakeyaml.constructor.SafeConstructor;

public class ClassX {
    /**
     * Carga la configuración desde una cadena YAML.
     * 
     * La función verifica las etiquetas peligrosas explícitas para prevenir la
     * instanciación de objetos. Utiliza {@link SafeConstructor} para limitar
     * la creación de objetos a tipos seguros (primitivos, Listas, Mapas, Cadenas, Fechas, Conjuntos).
     * 
     * @param yamlString La cadena YAML a cargar.
     * @return El objeto Java resultante de la carga del YAML. Puede ser un Map, List, String, etc.
     */
    public Object loadConfig(String yamlString) {
        // SafeConstructor is designed to prevent arbitrary object instantiation
        // by only allowing a limited set of safe types (primitives, List, Map, String, Date, Set).
        // It explicitly disallows !!fully.qualified.ClassName tags which are used for arbitrary object creation.
        Yaml yaml = new Yaml(new SafeConstructor());

        // The load method parses the YAML string and constructs a Java object graph
        // based on the rules defined by SafeConstructor.
        return yaml.load(yamlString);
    }
}
