import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor; // Use SafeConstructor for security

public class ClassX {

    /**
     * Clase de ejemplo para la configuración.
     * SnakeYAML puede mapear automáticamente YAML a instancias de esta clase
     * si los nombres de los campos coinciden y existen setters.
     */
    public static class SampleConfig {
        private String applicationName;
        private int version;
        private boolean enabled;

        // Getters y Setters son necesarios para que SnakeYAML pueda poblar el objeto
        public String getApplicationName() {
            return applicationName;
        }

        public void setApplicationName(String applicationName) {
            this.applicationName = applicationName;
        }

        public int getVersion() {
            return version;
        }

        public void setVersion(int version) {
            this.version = version;
        }

        public boolean isEnabled() {
            return enabled;
        }

        public void setEnabled(boolean enabled) {
            this.enabled = enabled;
        }

        @Override
        public String toString() {
            return "SampleConfig{" +
                   "applicationName='" + applicationName + '\'' +
                   ", version=" + version +
                   ", enabled=" + enabled +
                   '}';
        }
    }

    /**
     * Carga la configuración desde una cadena YAML.
     * 
     * La función verifica las etiquetas peligrosas explícitas para prevenir la
     * instanciación de objetos. Utiliza {@link SafeConstructor} para mitigar
     * vulnerabilidades de deserialización.
     *
     * @param <T> El tipo de objeto al que se debe mapear la configuración.
     * @param yamlString La cadena YAML que contiene la configuración.
     * @param type La clase del objeto de configuración esperado.
     * @return Un objeto de configuración del tipo especificado.
     * @throws org.yaml.snakeyaml.error.YAMLException Si el YAML contiene etiquetas peligrosas
     *                                                  o no es válido para el tipo especificado.
     */
    public <T> T loadConfig(String yamlString, Class<T> type) {
        // Utiliza SafeConstructor para prevenir la instanciación arbitraria de objetos
        // y mitigar vulnerabilidades de deserialización.
        Yaml yaml = new Yaml(new SafeConstructor());
        return yaml.loadAs(yamlString, type);
    }

    // Ejemplo de uso
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // YAML seguro
        String safeYaml = """
                applicationName: MySecureApp
                version: 1
                enabled: true
                """;

        // Intento de YAML inseguro (usando una etiqueta de tipo explícita peligrosa)
        String unsafeYamlAttempt = """
                !!javax.script.ScriptEngineManager []
                """;

        try {
            SampleConfig config = classX.loadConfig(safeYaml, SampleConfig.class);
            System.out.println("Configuración cargada de forma segura: " + config);
        } catch (Exception e) {
            System.err.println("Error al cargar configuración segura: " + e.getMessage());
        }

        try {
            // Esto debería lanzar una excepción porque SafeConstructor no permite
            // la instanciación de tipos arbitrarios como ScriptEngineManager.
            Object unsafeObject = classX.loadConfig(unsafeYamlAttempt, Object.class);
            System.out.println("Objeto inseguro cargado (no debería ocurrir): " + unsafeObject);
        } catch (org.yaml.snakeyaml.error.YAMLException e) {
            System.err.println("Error esperado al cargar YAML inseguro (protección activada): " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Otro error al cargar YAML inseguro: " + e.getMessage());
        }
    }
}
