    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Prevent XXE attacks by disabling DTDs and external entities
        try {
            // Disallow DOCTYPE declarations
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // This feature might not be supported by all XML processors.
            // Log a warning or handle appropriately if this is a critical requirement.
            // For this example, we proceed with other security measures.
            System.err.println("Warning: DocumentBuilderFactory does not support 'disallow-doctype-decl' feature. " + e.getMessage());
        }

        // General secure processing feature
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Disable external general entities
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

        // Disable external parameter entities
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Disable XInclude processing
        factory.setXIncludeAware(false);

        // Do not expand entity references
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parse the XML string from a byte array using UTF-8 encoding
        return builder.parse(new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8)));
