import java.io.IOException;

public class ClassX {
    /**
     * Analyse un document XML de manière sécurisée.
     *
     * La fonction vérifie la présence de déclarations 'DOCTYPE' pour prévenir les XXE
     * en désactivant leur traitement et celui des entités externes.
     * Si une déclaration DOCTYPE est présente, une SAXException sera levée.
     *
     * @param xmlString La chaîne XML à analyser.
     * @return Le document XML parsé et sécurisé.
     * @throws ParserConfigurationException Si une erreur de configuration du parseur survient.
     * @throws SAXException Si une erreur de parsing XML survient (incluant la détection de DOCTYPE).
     * @throws IOException Si une erreur d'entrée/sortie survient.
     */
    public Document parseAndSecureXml(String xmlString)
            throws ParserConfigurationException, SAXException, IOException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Désactiver le traitement des DTD et des entités externes pour prévenir les attaques XXE.
        // La présence d'une déclaration DOCTYPE avec la fonctionnalité 'disallow-doctype-decl' activée
        // entraînera une SAXException, agissant ainsi comme une vérification.
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Désactive complètement les déclarations DOCTYPE.
            // Si une DOCTYPE est présente, une SAXException sera levée.
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Désactive les entités générales externes.
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            // Désactive les entités de paramètres externes.
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Désactive l'inclusion XInclude.
            factory.setXIncludeAware(false);
            // Ne pas développer les références d'entités.
            factory.setExpandEntityReferences(false);
        } catch (ParserConfigurationException e) {
            // Gérer le cas où une fonctionnalité n'est pas supportée par l'implémentation du parseur.
            // Cela peut indiquer un problème avec la JVM ou la bibliothèque XML.
            System.err.println("Erreur de configuration du parseur lors de la désactivation des fonctionnalités de sécurité: " + e.getMessage());
            throw e; // Rejeter l'exception car la sécurité ne peut pas être garantie.
        }

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parse le document XML à partir d'un ByteArrayInputStream.
        // Utiliser getBytes() sans spécifier d'encodage peut être risqué si l'XML n'est pas UTF-8
        // et ne spécifie pas son propre encodage. Pour une robustesse maximale,
        // il faudrait utiliser xmlString.getBytes(StandardCharsets.UTF_8) ou gérer l'encodage.
        return builder.parse(new ByteArrayInputStream(xmlString.getBytes()));
    }
}
