    /**
     * Se conecta a una API externa verificando la clave (simulada).
     *
     * @return true si la conexión es exitosa, false en caso contrario.
     */
    public boolean connectToApi() {
        String apiKey = getApiKey();

        if (apiKey == null || apiKey.isEmpty()) {
            System.err.println("Error: No se pudo obtener la clave de la API.");
            return false;
        }

        System.out.println("Intentando conectar a la API con la clave: [" + apiKey + "]");
        // Aquí iría la lógica real de conexión a la API, por ejemplo, usando un cliente HTTP
        // y enviando la clave para autenticación.
        // Por ahora, simulamos una conexión exitosa si la clave no es nula/vacía.
        System.out.println("Conexión a la API simulada exitosa.");
        return true;
