     */
    private String getApiKey() {
        try {
            // Decodifica la clave de Base64 a un array de bytes
            byte[] decodedBytes = Base64.getDecoder().decode(OBFUSCATED_API_KEY);
            // Convierte los bytes decodificados a una cadena usando UTF-8
            return new String(decodedBytes, StandardCharsets.UTF_8);
