    private boolean verifyApiKey(String apiKey) {
        if (apiKey == null || apiKey.isEmpty()) {
            System.out.println("La clave API no puede ser nula o vacía.");
            return false;
        }
        // Simulación de verificación: compara con una clave esperada
        return EXPECTED_API_KEY.equals(apiKey);
    }

