    private String decodeApiKey() {
        try {
            byte[] decodedBytes = Base64.getDecoder().decode(OBFUSCATED_API_KEY);
            return new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            System.err.println("Virhe API-avaimen dekoodauksessa: " + e.getMessage());
            return null;
        }
