import java.util.Base64;

public class ClassX {

    private String encryptedApiKey; // Το κλειδί API αποθηκευμένο σε κρυπτογραφημένη μορφή (π.χ. Base64)

    /**
     * Κατασκευαστής για την ClassX.
     * Αρχικοποιεί το κρυπτογραφημένο κλειδί API.
     *
     * @param encryptedApiKey Το κρυπτογραφημένο κλειδί API.
     */
    public ClassX(String encryptedApiKey) {
        this.encryptedApiKey = encryptedApiKey;
    }

    /**
     * Ανακτά και αποκρυπτογραφεί το κλειδί API.
     * Υποθέτει ότι η "κρυπτογράφηση" είναι απλώς κωδικοποίηση Base64 για αυτό το παράδειγμα.
     * Σε ένα πραγματικό σενάριο, θα υπήρχε μια πιο ισχυρή μέθοδος αποκρυπτογράφησης.
     *
     * @return Το αποκρυπτογραφημένο κλειδί API.
     * @throws IllegalArgumentException εάν το κρυπτογραφημένο κλειδί δεν είναι έγκυρο Base64.
     */
    private String getDecryptedApiKey() {
        try {
            byte[] decodedBytes = Base64.getDecoder().decode(encryptedApiKey);
            return new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            System.err.println("Σφάλμα: Το κρυπτογραφημένο κλειδί δεν είναι έγκυρο Base64. " + e.getMessage());
            throw e; // Προωθεί το σφάλμα για περαιτέρω χειρισμό
        }
    }

    /**
     * Συνδέεται σε μια εξωτερική API ελέγχοντας το κλειδί (Προσομοιωμένο).
