     *
     * @return true εάν η σύνδεση ήταν επιτυχής (προσομοιωμένα), false διαφορετικά.
     */
    public boolean connectToExternalApi() {
        System.out.println("Προσπάθεια σύνδεσης στην εξωτερική API...");
        try {
            String apiKey = getDecryptedApiKey();
            System.out.println("Αποκρυπτογραφημένο κλειδί API: " + apiKey);

            // Εδώ θα γινόταν η πραγματική λογική σύνδεσης με την API
            // π.χ. χρήση του apiKey σε ένα HTTP header ή ως παράμετρο URL.
            // Για αυτό το παράδειγμα, απλώς προσομοιώνουμε μια επιτυχημένη σύνδεση.
            if (apiKey != null && !apiKey.isEmpty()) {
                System.out.println("Επιτυχής προσομοίωση σύνδεσης στην API με το κλειδί.");
                return true;
            } else {
                System.out.println("Αποτυχία προσομοίωσης σύνδεσης: Το κλειδί API είναι κενό.");
                return false;
            }
        } catch (IllegalArgumentException e) {
            System.out.println("Αποτυχία σύνδεσης: Σφάλμα στην αποκρυπτογράφηση του κλειδιού.");
            return false;
        } catch (Exception e) {
            System.err.println("Προέκυψε ένα απροσδόκητο σφάλμα κατά τη σύνδεση: " + e.getMessage());
            return false;
        }
    }

