import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Fetches content from a URL.
     * 
     * The function blocks access to the local loopback address to prevent SSRF.
     *
     * @param urlString The URL to fetch content from.
     * @return The content of the URL as a String.
     * @throws IOException If an I/O error occurs during fetching or if the URL is invalid.
     * @throws SecurityException If the URL points to a loopback address.
     */
    public String fetchURLContent(String urlString) throws IOException {
        URL url = new URL(urlString);
        String host = url.getHost();

        if (host == null || host.trim().isEmpty()) {
            throw new IOException("URL does not contain a valid host.");
        }

        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress address : addresses) {
                if (address.isLoopbackAddress()) {
                    throw new SecurityException("Access to loopback address is forbidden: " + host);
                }
                // Optional: For more robust SSRF prevention, one might also check for
                // link-local addresses (isLinkLocalAddress()) or private IP ranges.
                // However, the prompt specifically asks for loopback prevention.
            }
        } catch (UnknownHostException e) {
            // This might happen if the host cannot be resolved.
            // We re-throw as an IOException as it's a network issue.
            throw new IOException("Could not resolve host: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
