            throw new IllegalArgumentException("La URL no puede ser nula o vacía.");
        }

        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Formato de URL inválido: " + urlString + " - " + e.getMessage());
