import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     *
     * @param urlString Die URL, deren Inhalt abgerufen werden soll.
     * @return Der Inhalt der URL als String.
     * @throws IOException Wenn ein E/A-Fehler auftritt, die URL ungültig ist oder eine lokale Loopback-Adresse darstellt.
     */
    public String fetchUrlContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IOException("Ungültiges URL-Format: " + urlString, e);
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IOException("URL enthält keinen Host: " + urlString);
        }

        try {
            InetAddress address = InetAddress.getByName(host);
            if (address.isLoopbackAddress()) {
                throw new IOException("Zugriff auf Loopback-Adresse (" + host + ") ist aus Sicherheitsgründen nicht erlaubt.");
