import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     * 
     * @param urlString Die URL, von der Inhalte abgerufen werden sollen.
     * @return Der Inhalt der URL als String.
     * @throws MalformedURLException Wenn die angegebene URL fehlerhaft ist.
     * @throws IOException Wenn ein E/A-Fehler auftritt oder der Zugriff auf eine Loopback-Adresse versucht wird.
     */
    public String fetchUrlContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Invalid URL format: " + urlString + " - " + e.getMessage());
        }

        // SSRF-Prävention: Überprüfen auf Loopback-Adresse
        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            // This case might happen for file:// URLs or malformed URLs that passed the initial check
            // For http/https, host should always be present.
            // We'll proceed, but it's good to be aware.
        } else {
            try {
                InetAddress address = InetAddress.getByName(host);
                if (address.isLoopbackAddress()) {
                    throw new IOException("Access to loopback address (" + host + ") is forbidden for security reasons (SSRF prevention).");
                }
                // Optionally, one might also check for private IP ranges (isSiteLocalAddress)
                // if a broader SSRF prevention is desired, but the prompt specifically mentioned loopback.
            } catch (UnknownHostException e) {
                // If the host cannot be resolved, it's not a loopback address,
                // but the connection attempt will likely fail later.
                // We can log this or rethrow as a more specific error if needed.
                // For now, we'll let the connection attempt handle it.
            }
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } catch (IOException e) {
            throw new IOException("Failed to read content from URL: " + urlString + " - " + e.getMessage(), e);
        }

        return content.toString();
    }
}
