import java.net.UnknownHostException;

public class ClassX {
    /**
     * Получает содержимое по URL.
     *
     * Функция блокирует доступ к локальному адресу обратной связи, чтобы предотвратить SSRF.
     *
     * @param urlString Строка URL для получения содержимого.
     * @return Содержимое, полученное по URL.
     * @throws IOException Если произошла ошибка ввода-вывода или URL является локальным адресом обратной связи.
     * @throws MalformedURLException Если строка URL имеет неверный формат.
     * @throws IllegalArgumentException Если URL не содержит хоста.
     */
    public String getContentFromUrl(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Invalid URL format: " + urlString + ". " + e.getMessage());
        }

        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("URL does not contain a host: " + urlString);
        }

        try {
            InetAddress address = InetAddress.getByName(host);
            if (address.isLoopbackAddress()) {
                throw new IOException("Access to loopback address is blocked to prevent SSRF: " + host);
            }
            // For more comprehensive SSRF protection, you might also check for private IP ranges:
            // if (address.isSiteLocalAddress()) {
            //     throw new IOException("Access to private IP address is blocked to prevent SSRF: " + host);
            // }
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's not a loopback address.
            // The subsequent url.openStream() call will handle the unknown host if it's truly unreachable.
            // We proceed here as the primary goal is to block *known* loopback addresses.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
